xianding:dcshiyu.code:
{
    audio: 2,
    trigger: { global: "phaseBegin" },
    round: 1,
    filter(event, player) {
      return player != event.player;
    },
    async cost(event, trigger, player) {
      const target = trigger.player;
      const result = await player.chooseButton({
        createDialog: [`识预：猜测${get.translation(target)}本回合是否会使用这些类型的牌`, [["basic", "trick", "equip"].map((i) => ["", "", `caoying_${i}`]), "vcard"]],
        selectButton: [1, 3],
        ai(button) {
          const { player: player2, target: target2 } = get.event();
          if (get.attitude(player2, target2) > 0 || target2.hasCards("j", (card) => get.name(card) == "lebu")) return 0;
          const link = button.link[2].slice(8);
          if (link == "basic") return 1;
          return 0.5 - Math.random();
        }
      }).set("target", target).forResult();
      if (result?.bool && result.links?.length) {
        event.result = {
          bool: true,
          targets: [target],
          cost_data: result.links.map((type) => type[2].slice(8))
        };
      }
    },
    async content(event, trigger, player) {
      const {
        targets: [target],
        cost_data: types1
      } = event;
      player.when({ global: "phaseEnd" }).filter((evt) => evt.player == target).step(async (event2, trigger2, player2) => {
        const types2 = target.getHistory("useCard").flatMap((evt) => get.type2(evt.card)).unique();
        let num1 = types1.slice().removeArray(types2).length, num2 = types1.length - num1;
        if (num2 > 0) {
          if (target.hasCards("he")) {
            await player2.gainPlayerCard({ forced: true, position: "he", target, selectButton: Math.min(target.countCards("he"), num2) });
          }
          player2.addTempSkill("dcshiyu_nodamage", "roundStart");
          player2.markAuto("dcshiyu_nodamage", [target]);
        }
        if (num1 > 0) {
          while (num1--) {
            await target.damage({ num: 1, source: player2 });
            await player2.damage({ num: 1, source: target });
          }
        } else {
          delete player2.storage["dcshiyu_roundcount"];
        }
      });
    },
    subSkill: {
      nodamage: {
        charlotte: true,
        intro: { content: "防止$本轮下次对你造成的伤害" },
        onremove: true,
        forced: true,
        firstDo: true,
        trigger: { player: "damageBegin4" },
        filter(event, player) {
          return event.source && player.getStorage("dcshiyu_nodamage").includes(event.source);
        },
        async content(event, trigger, player) {
          trigger.cancel();
          player.unmarkAuto(event.name, [trigger.source]);
        }
      }
    }
  }

xianding:dcshuaijian.code:
{
    audio: 2,
    trigger: { player: ["phaseBegin", "phaseEnd"] },
    filter(event, player) {
      return ["h", "e"].some((pos) => game.hasPlayer((current) => current.hasCards(pos)));
    },
    async cost(event, trigger, player) {
      event.result = await player.chooseButtonTarget({
        createDialog: [
          "率俭：你可以令一名手牌数最多或装备区牌数最多的一名角色弃牌",
          [
            [
              ["h", "手牌最多"],
              ["e", "装备区牌最多"]
            ],
            "tdnodes"
          ]
        ],
        filterButton(button) {
          const pos = button.link;
          return game.hasPlayer((current) => current.hasCards(pos));
        },
        filterTarget(card, player2, target) {
          if (!ui.selected.buttons?.length) return false;
          const pos = ui.selected.buttons[0].link;
          return !game.hasPlayer((current) => current.countCards(pos) > target.countCards(pos)) && target.hasCards(pos);
        },
        ai1(button) {
          const player2 = get.player();
          if (game.hasPlayer((current) => current.hasCards("e"))) {
            const targets = game.filterPlayer((target) => !game.hasPlayer((current) => current.countCards("e") > target.countCards("e")) && target.hasCards("e"));
            if (targets.some((target) => get.attitude(player2, target) < 0) && game.hasPlayer((current) => get.recoverEffect(current, player2, player2) > 0)) {
              return button.link == "e";
            }
          }
          if (game.hasPlayer((current) => current.hasCards("h"))) {
            const targets = game.filterPlayer((target) => !game.hasPlayer((current) => current.countCards("h") > target.countCards("h")) && target.hasCards("h"));
            if (targets.some((target) => get.attitude(player2, target) < 0)) {
              return button.link == "h";
            }
          }
          return 0;
        },
        ai2(target) {
          const player2 = get.player();
          if (!ui.selected.buttons?.length) return 0;
          const pos = ui.selected.buttons[0].link;
          return -get.attitude(player2, target) * target.countCards(pos);
        }
      }).forResult();
      if (event.result?.bool && event.result.links?.length) {
        event.result.cost_data = event.result.links;
      }
    },
    async content(event, trigger, player) {
      const {
        targets: [target],
        cost_data: [pos]
      } = event;
      let num = Math.max(...game.filterPlayer((current) => current != target).map((current) => current.countCards(pos)));
      num = Math.max(1, target.countCards(pos) - num + 1);
      let result = await target.chooseToDiscard({ forced: true, position: pos, selectCard: [num, Infinity] }).forResult();
      if (result?.cards?.length) {
        num = result.cards.length;
        if (pos == "e" && !game.hasPlayer((current) => current.isDamaged())) {
          return;
        }
        const prompt = `率俭：令一名角色${pos == "h" ? `摸${get.cnNumber(num)}张牌` : `回复${num}点体力`}`;
        result = await player.chooseTarget({
          prompt,
          forced: true,
          filterTarget(card, player2, target2) {
            return get.event().pos == "h" || target2.isDamaged();
          },
          ai(target2) {
            const player2 = get.player();
            return get.event().pos == "h" ? get.effect(target2, { name: "draw" }, player2, player2) : get.recoverEffect(target2, player2, player2);
          }
        }).set("pos", pos).forResult();
        if (result?.bool && result.targets?.length) {
          const target2 = result.targets[0];
          player.line(target2);
          await target2[pos == "h" ? "draw" : "recover"](num);
        }
      }
    }
  }

xianding:dcranlv.code:
{
    audio: 2,
    init(player) {
      player.storage["dcranlv"] = [true, true, true];
    },
    trigger: { global: "damageEnd" },
    filter(event, player) {
      if (!player.getStorage("dcranlv")?.length) {
        return false;
      }
      let num = 0;
      for (const i of player.getStorage("dcranlv")) {
        if (i) {
          num++;
        }
      }
      return !event.hasNature("linked") && num > 0;
    },
    async cost(event, trigger, player) {
      const choiceList = ["横置或重置至多两名角色", "摸两张牌", "弃置一名角色两张牌"];
      const controls = [];
      for (const i of [0, 1, 2]) {
        if (player.getStorage("dcranlv")[i]) {
          controls.push(`选项${["一", "二", "三"][i]}`);
        } else {
          choiceList[i] = `<span style="text-decoration: line-through;">${choiceList[i]}</span>`;
        }
      }
      controls.push("cancel2");
      const result = await player.chooseControl({
        prompt: "燃缕：是否选择一项执行？",
        choiceList,
        controls,
        ai: () => {
          const player2 = get.player();
          const controls2 = get.event().controls;
          if (controls2.includes("选项二")) {
            return "选项二";
          }
          if (controls2.includes("选项三") && game.countPlayer((current) => {
            return get.effect(current, { name: "guohe_copy2" }, player2, player2) && current.hasDiscardableCards(player2, "he");
          })) {
            return "选项三";
          }
          return "选项一";
        }
      }).set("controls", controls).forResult();
      event.result = {
        bool: result.control !== "cancel2",
        cost_data: {
          control: result.control
        }
      };
    },
    async content(event, trigger, player) {
      const control = event.cost_data.control;
      const index = ["一", "二", "三"].indexOf(control[2]);
      player.storage["dcranlv"][index] = false;
      if (index === 0) {
        const result = await player.chooseTarget({
          prompt: "选择横置或重置至多2名角色",
          forced: true,
          selectTarget: [1, 2],
          ai(target) {
            const player2 = get.player();
            if (player2 === target) {
              if (player2.hasSkill("dcjuexun")) {
                return player2.isLinked() ? 1 : 5;
              }
              return player2.isLinked() ? 2 : 0;
            }
            if (get.attitude(player2, target)) {
              return target.isLinked() ? 3 : 0;
            }
            return target.isLinked() ? 0 : 4;
          }
        }).forResult();
        const targets = result.targets.sortBySeat();
        player.line(targets);
        for (const i of targets) {
          await i.link();
        }
      } else if (index === 1) {
        await player.draw(2);
      } else {
        const result = await player.chooseTarget({
          prompt: "选择一名角色并弃置其两张牌",
          forced: true,
          filterTarget(card, player2, target2) {
            return target2.countDiscardableCards(player2, "he");
          },
          ai: (target2) => {
            const player2 = get.player();
            return get.effect(target2, { name: "guohe_copy2" }, player2, player2);
          }
        }).forResult();
        const target = result.targets[0];
        await player.discardPlayerCard(target, true, "he", 2);
      }
    }
  }

xianding:dcjuexun.code:
{
    audio: 2,
    usable: 1,
    trigger: {
      player: "loseAfter",
      global: ["equipAfter", "addJudgeAfter", "gainAfter", "loseAsyncAfter", "addToExpansionAfter"]
    },
    filter(event, player) {
      return event.getl?.(player)?.hs?.length > 0 && player.isMinHandcard();
    },
    async content(event, trigger, player) {
      if (player.hasSkill("dcranlv") && player.storage["dcranlv"]?.length) {
        player.storage["dcranlv"] = [true, true, true];
      }
      const { bool } = await player.chooseBool({
        prompt: "是否对自己造成一点火焰伤害？",
        ai() {
          const player2 = get.player();
          return player2.hp === 2 && game.hasPlayer((current) => current.isLinked() && get.attitude(player2, current) < 0);
        }
      }).forResult();
      if (bool) {
        await player.damage("fire");
        if (player.isMinHp()) {
          const targets = game.filterPlayer((current) => current !== player && current.isLinked());
          player.line(targets);
          targets.forEach((i) => {
            i.addSkill("dcjuexun_eff");
            i.addMark("dcjuexun_eff", 1);
          });
        }
      }
    },
    check: () => true,
    subSkill: {
      eff: {
        forced: true,
        charlotte: true,
        popup: false,
        trigger: {
          player: "damageBegin3"
        },
        filter(event, player) {
          return event.hasNature("fire") && player.countMark("dcjuexun_eff");
        },
        async content(event, trigger, player) {
          trigger.num += player.countMark("dcjuexun_eff");
          player.removeSkill("dcjuexun_eff");
        },
        mark: true,
        intro: {
          onremove: true,
          content: "下次受到的火焰伤害+#"
        }
      }
    }
  }

xianding:dccaiyun.code:
{
    audio: 2,
    usable: 1,
    enable: "phaseUse",
    filterTarget: lib.filter.notMe,
    async content(event, trigger, player) {
      const target = event.targets[0];
      const types = lib.inpile.map((name) => get.type2(name)).unique();
      const { control } = await player.chooseControl({
        prompt: `才韵：与${get.translation(target)}各获得一张指定类型的牌`,
        controls: types,
        ai: () => {
          return "trick";
        }
      }).forResult();
      for (const i of [player, target]) {
        const card = get.cardPile2((card2) => get.type2(card2) === control, "random");
        if (card) {
          await i.gain(card, "gain2");
        } else {
          i.chat("没牌");
        }
      }
      for (const i of [player, target]) {
        i.addSkill("dccaiyun_eff");
        i.storage["dccaiyun_eff"] = [control, 2];
      }
      player.when({ player: "phaseBegin" }).then(() => {
        player.removeSkill("dccaiyun_eff");
        target.removeSkill("dccaiyun_eff");
      }).vars({ target });
    },
    subSkill: {
      eff: {
        charlotte: true,
        forced: true,
        trigger: { player: "useCard" },
        filter(event, player) {
          const type = player.getStorage("dccaiyun_eff")[0];
          return get.type2(event.card) === type && player.getStorage("dccaiyun_eff")[1] > 0;
        },
        async content(event, trigger, player) {
          const type = player.getStorage("dccaiyun_eff")[0];
          const cards2 = [];
          for (const i of [0, 1]) {
            const card = get.cardPile2((card2) => get.type2(card2) !== type, "random");
            if (card) {
              cards2.push(card);
            }
          }
          if (cards2.length) {
            await player.gain(cards2, "gain2");
          } else {
            player.chat("无牌");
          }
          player.storage["dccaiyun_eff"][1]--;
        },
        mark: true,
        intro: {
          onremove: true,
          content(storage, player) {
            return `使用${get.translation(storage[0])}牌后，随机获得牌堆中与之类型不同的2张牌。（剩余${get.cnNumber(storage[1])}次）`;
          }
        }
      }
    },
    ai: {
      order: 10,
      result: {
        target: 1
      }
    }
  }

xianding:dcqieyan.code:
{
    audio: 2,
    forced: true,
    trigger: {
      global: ["useCard", "useCardAfter"]
    },
    filter(event, player, name) {
      const target = event.player;
      if (target === player) {
        return false;
      }
      if (name === "useCard") {
        return event.card && (get.type(event.card) === "trick" || get.type(event.card) === "basic" && !["shan", "tao", "jiu", "du"].includes(event.card.name)) && get.distance(target, player) <= 1;
      } else {
        return event.targets?.includes(player) && get.type(event.card) !== "delay";
      }
    },
    async content(event, trigger, player) {
      if (event.triggername === "useCard") {
        trigger.directHit.add(player);
      } else {
        const target = trigger.player;
        const bool1 = target.inRange(player);
        target.addTempSkill("dcqieyan_distance");
        const map = target.getStorage("dcqieyan_distance", /* @__PURE__ */ new Map());
        const num = (map.has(player) ? map.get(player) : 0) + 1;
        map.set(player, num);
        target.setStorage("dcqieyan_distance", map, true);
        const bool2 = target.inRange(player);
        if (bool1 && !bool2) {
          await player.recover();
          await player.draw(2);
        }
      }
    },
    subSkill: {
      distance: {
        charlotte: true,
        onremove: true,
        intro: {
          markcount: () => null,
          content(storage, player) {
            const map = player.getStorage("dcqieyan_distance", /* @__PURE__ */ new Map());
            if (!map.size) {
              return "无效果";
            }
            return Array.from(map.keys()).map((current) => `计算与${get.translation(current)}的距离+${map.get(current)}`).join("<br>");
          }
        },
        mod: {
          globalFrom(from, to, num) {
            const map = from.getStorage("dcqieyan_distance", /* @__PURE__ */ new Map());
            if (map.has(to)) {
              return num + map.get(to);
            }
          }
        }
      }
    }
  }

