xianding:dcsbjuzhan.code:
{
    audio: 2,
    usable: 1,
    trigger: {
      player: "useCardToPlayered",
      global: "useCardAfter"
    },
    filter(event, player, name) {
      const card = event.card;
      if (get.name(card) !== "sha" && get.type(card) !== "trick") {
        return false;
      }
      if (name === "useCardToPlayered") {
        return event.isFirstTarget && player.countCards("h") >= player.hp && player.countDiscardableCards(player, "h");
      } else {
        if (!event.targets?.includes(player) || event.player === player) {
          return false;
        }
        return player.countCards("h") <= player.hp && player.countCards("h", (card0) => {
          return player.canUse(get.autoViewAs({ name: card.name, nature: card.nature }, [card0]), event.player, false, false);
        });
      }
    },
    async cost(event, trigger, player) {
      let result;
      if (event.triggername === "useCardToPlayered") {
        const result0 = await player.chooseToDiscard({
          prompt: get.prompt("dcsbjuzhan"),
          prompt2: `弃置一张手牌，令${get.translation(trigger.card)}额外结算一次`,
          position: "h",
          ai: (card) => {
            const player2 = get.player();
            const triggerx = get.event().triggerx;
            if (triggerx.card.name === "tiesuo") {
              return -1;
            }
            if (["shunshou", "guohe"].includes(triggerx.card.name) && (triggerx.targets[0].countCards("he") <= 1 || get.attitude(player2, triggerx.targets[0]) > 0)) {
              return -1;
            }
            if (get.effect(triggerx.targets[0], triggerx.card, player2, player2)) {
              return -1;
            }
            return 6 - get.value(card, player2);
          }
        }).set("triggerx", trigger).forResult();
        result = {
          bool: result0.bool
        };
      } else {
        const result0 = await player.chooseCard({
          prompt: get.prompt("dcsbjuzhan"),
          prompt2: `将一张手牌当${trigger.card.nature ? get.translation(trigger.card.nature) : ""}【${get.translation(trigger.card.name)}】对${get.translation(trigger.player)}使用`,
          position: "h",
          filterCard(card, player2) {
            return player2.canUse(get.autoViewAs({ name: trigger.card.name, nature: trigger.card.nature }, [card]), trigger.player, false, false);
          },
          ai: (card) => {
            const player2 = get.player();
            const triggerx = get.event().triggerx;
            const cardx = get.autoViewAs({ name: triggerx.card.name, nature: triggerx.card.nature }, [card]);
            return get.effect(triggerx.player, cardx, player2, player2);
          }
        }).set("triggerx", trigger).forResult();
        result = {
          bool: result0.bool,
          cost_data: {
            cards: result0.cards
          }
        };
      }
      event.result = result;
    },
    async content(event, trigger, player) {
      if (event.triggername === "useCardToPlayered") {
        trigger.getParent().effectCount++;
        game.log(`${get.translation(player)}令${get.translation(trigger.card)}额外结算一次`);
      } else {
        const cardx = get.autoViewAs({ name: trigger.card.name, nature: trigger.card.nature }, event.cost_data.cards);
        if (!player.canUse(cardx, trigger.player, false, false)) {
          return;
        }
        await player.useCard(cardx, event.cost_data.cards, trigger.player, false);
      }
    }
  }

xianding:dcxunxiang.code:
{
    audio: 2,
    trigger: { player: "useCardAfter" },
    filter(event, player) {
      return !player.getStorage("dcxunxiang_used").includes(get.suit(event.card));
    },
    async content(event, trigger, player) {
      const suit = get.suit(trigger.card);
      player.addTempSkill(`${event.name}_used`);
      player.markAuto(`${event.name}_used`, [suit]);
      const num = 4 + player.countMark(event.name);
      let cards2 = get.cards(num, true);
      await player.viewCards("寻香：牌堆顶的牌", cards2);
      player.setStorage(
        `${event.name}_used2`,
        cards2.filter((card) => get.suit(card) !== suit),
        true
      );
      cards2 = cards2.filter((card) => get.suit(card) === suit);
      if (cards2.length) {
        await player.gain({ cards: cards2, animate: "draw" });
      } else {
        player.popup("杯具");
      }
      const suits = player.getAllHistory("useCard").slice().flatMap((evt) => get.suit(evt.card)).unique();
      let mark = 0;
      if (suits.length >= 2 && num < 5) {
        mark++;
      }
      if (suits.length >= 4 && num < 6) {
        mark++;
      }
      if (mark > 0) {
        player.addMark(event.name, mark, false);
      }
    },
    intro: { content: "此技能观看牌数+#" },
    subSkill: {
      used: {
        charlotte: true,
        onremove(player, skill) {
          delete player.storage[skill];
          delete player.storage[`${skill}2`];
        },
        intro: {
          name: "寻香",
          mark(dialog, storage, player) {
            dialog.addText(`本回合已使用${get.translation(storage)}牌`);
            const cards2 = player.storage.dcxunxiang_used2;
            if (cards2?.length) {
              dialog.addText("上次发动此技能亮出的牌");
              dialog.addAuto(cards2);
            }
          }
        },
        marktext: "香"
      }
    }
  }

xianding:dczhiyao.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event, player) {
      return player.hasCards("he", (card) => get.info("dczhiyao").filterCard(card, player)) && game.hasPlayer((current) => get.info("dczhiyao").filterTarget(null, player, current));
    },
    filterCard(card, player) {
      if (!["tao", "jiu", "shunshou", "wugu"].includes(card.name) && !["equip4", "equip3", "equip3_4"].includes(get.subtype(card))) {
        return false;
      }
      return lib.filter.cardDiscardable(card, player, "dczhiyao");
    },
    selectCard: [1, Infinity],
    position: "he",
    complexCard: true,
    check(card) {
      if (!ui.selected.cards?.length) {
        return 114514 - get.value(card);
      }
      return 0;
    },
    filterTarget(card, player, target) {
      return !player.getStorage("dczhiyao_used").includes(target);
    },
    lose: false,
    discard: false,
