          }
          choiceList[i] = `<span style="opacity:0.5">'${choiceList[i]}</span>`;
          controlList[i] = "";
        }
      }
      controlList = controlList.filter((i) => i !== "");
      const result = await player.chooseControl({
        prompt: get.prompt(event.skill),
        controls: controlList,
        choiceList,
        ai: () => {
          const { player: player2, list } = get.event();
          if (list.includes("弃置牌") && player2.hasCards("he", (i) => {
            if (["wuxie", "shan", "tao"].includes(get.name(i, player2))) {
              return false;
            }
            let val = 5 - get.value(i, player2);
            if (player2.getStorage("dcsbfangong")) {
              val += 1;
            }
            return val >= 3;
          })) {
            return "弃置牌";
          }
          if (list.includes("失去体力") && player2.hp >= 3) {
            return "失去体力";
          }
          return "cancel2";
        }
      }).set("list", choiceList).forResult();
      event.result = {
        bool: result?.control !== "cancel2",
        cost_data: result?.control,
        targets: [trigger.player]
      };
    },
    async content(event, trigger, player) {
      const user = event.targets[0];
      if (!user?.isIn()) {
        return;
      }
      user.addTempSkill("dcsbyouyi_sha", "phaseAnyAfter");
      user.addMark("dcsbyouyi_sha", 1, false);
      const control = event.cost_data;
      if (control === "弃置牌") {
        player.addTempSkill("dcsbyouyi_used");
        player.markAuto("dcsbyouyi_used", ["discard"]);
        const result = await player.chooseToDiscard({
          position: "he",
          selectCard: [1, Infinity],
          forced: true,
          ai: (card) => {
            const player2 = get.player();
            if (["wuxie", "shan", "tao"].includes(get.name(card, player2))) {
              return 0;
            }
            let val = 5 - get.value(card, player2);
            if (player2.getStorage("dcsbfangong")) {
              val += 1;
            }
            if (val < 3) {
              val = 0;
            }
            return val;
          }
        }).forResult();
        if (!result?.cards?.length) {
          return;
        }
        await player.draw();
        if (!player.storage["dcsbyouyi_eff"]) {
          player.storage["dcsbyouyi_eff"] = {
            draw: 0,
            recover: 0,
            sum: 0
          };
        }
        player.storage["dcsbyouyi_eff"].draw += result.cards.length;
        player.storage["dcsbyouyi_eff"].sum += result.cards.length;
      } else {
        player.addTempSkill("dcsbyouyi_used");
        player.markAuto("dcsbyouyi_used", ["loseHp"]);
        const result = await player.chooseControl({
          controls: ["1", "2", "3", "4"],
          prompt: "选择失去的体力值",
          ai: () => {
            const player2 = get.player();
            return String(Math.min(4, Math.max(1, player2.hp - 2)));
          }
        }).forResult();
        const num = Number(result.control);
        await player.loseHp(num);
        const result1 = await player.chooseTarget({
          prompt: `令一名角色摸${get.cnNumber(num)}张牌`,
          forced: true,
          ai: (target2) => {
            return get.attitude(get.player(), target2);
          }
        }).forResult();
        const target = result1.targets[0];
        player.line(target);
        await target.draw(num);
        if (!player.storage["dcsbyouyi_eff"]) {
          player.storage["dcsbyouyi_eff"] = {
            draw: 0,
            recover: 0,
            sum: 0
          };
        }
        player.storage["dcsbyouyi_eff"].recover += num;
        player.storage["dcsbyouyi_eff"].sum += num;
      }
      const sum = player.storage["dcsbyouyi_eff"]?.sum;
      if (!sum) {
        return;
      }
      if (sum >= 7) {
        player.storage["dcsbyouyi_eff"].sum = sum % 7;
        if (player.hasSkill("dcsbfangong", null, false, false) && player.awakenedSkills.includes("dcsbfangong")) {
          game.log(player, "重置了", "#g【返攻】");
          player.restoreSkill("dcsbfangong");
        }
      }
    },
    group: "dcsbyouyi_eff",
    subSkill: {
      sha: {
        charlotte: true,
        mark: true,
        intro: { content: "本阶段使用【杀】次数+#" },
        mod: {
          cardUsable(card, player, num) {
            if (card.name === "sha") {
              return num + player.countMark("dcsbyouyi_sha");
            }
          }
        },
        onremove: true
      },
      used: {
        charlotte: true,
        sub: true,
        mark: true,
        intro: {
          content(storage, player) {
            let str = "";
            if (!player.storage["dcsbyouyi_eff"]) {
              return str;
            }
            const { draw, recover } = player.storage["dcsbyouyi_eff"];
            if (draw) {
              str += `<li>本回合结束时，摸${draw}张牌。`;
            }
            if (draw && recover) {
              str += "<br>";
            }
            if (recover) {
              str += `<li>本回合结束时，回复${recover}点体力。`;
            }
            return str;
          }
        },
        onremove: true
      },
      eff: {
        audio: "dcsbyouyi",
        charlotte: true,
        forced: true,
        popup: false,
        trigger: { global: ["phaseEnd", "phaseBeginStart"] },
        filter(event, player) {
          if (!player.storage["dcsbyouyi_eff"]) {
            return false;
          }
          const { draw, recover } = player.storage["dcsbyouyi_eff"];
          return draw || recover;
        },
        async content(event, trigger, player) {
          if (!player.storage["dcsbyouyi_eff"]) {
            return;
          }
          if (event.triggername === "phaseEnd") {
            const { draw, recover } = player.storage["dcsbyouyi_eff"];
            if (draw) {
              player.draw(draw);
            }
            if (recover) {
              player.recover(recover);
            }
          } else {
            player.storage["dcsbyouyi_eff"].draw = 0;
            player.storage["dcsbyouyi_eff"].recover = 0;
          }
        }
      }
    }
  }

