            _status.event.extraAIed = true;
            const { player: player2, num: num2, extraAI, check } = get.event();
            extraAI(check, player2, num2);
          }
          return 0;
        },
        check(target, targets2) {
          let damage = get.damageEffect(target, player, player);
          if (damage <= 0) {
            return 0;
          }
          if (ui.selected.targets.includes(target)) {
            damage *= 1 - get.numOf(ui.selected.targets, target) / get.event().num;
          }
          return damage;
        },
        extraAI(check, player2, num2) {
          const event2 = get.event();
          const range = [num2, num2];
          const forced = event2.forced;
          let ok = false;
          let iwhile = 100;
          const targets2 = game.filterPlayer((current) => current !== player2);
          let i;
          let targets22;
          while (iwhile--) {
            if (ui.selected.targets.length >= range[0]) {
              ok = true;
            }
            targets22 = targets2.slice(0);
            let ix = 0;
            CacheContext.setCacheContext(new CacheContext({ lib, game, get }));
            CacheContext.setInCacheEnvironment(true);
            let checkix = check(targets2[0], targets22);
            for (i = 1; i < targets2.length; i++) {
              const checkixtmp = check(targets2[i], targets22);
              if (checkixtmp > checkix) {
                ix = i;
                checkix = checkixtmp;
              }
            }
            if (check(targets2[ix]) <= 0) {
              if (!forced || ok) {
                CacheContext.setInCacheEnvironment(false);
                CacheContext.removeCacheContext();
                return;
              }
            }
            CacheContext.setInCacheEnvironment(false);
            CacheContext.removeCacheContext();
            targets2[ix].classList.add("selected");
            ui.selected.targets.push(targets2[ix]);
            game.check();
            if (ui.selected.targets.length >= range[0]) {
              ok = true;
            }
            if (ui.selected.targets.length >= range[1]) {
              return;
            }
          }
        },
        num
