    intro: { content: `已移除选项：$` },
    subSkill: {
      effect: {
        charlotte: true,
        onremove: true,
        intro: { content: "摸牌阶段摸牌数和使用【杀】的次数上限+#" },
        trigger: { player: "phaseDrawBegin2" },
        forced: true,
        popup: false,
