          cardUsable(card, player, num) {
            if (card.name === "sha") {
              return num + player.countMark("mogui_effect");
            }
          }
        }
      },
      hand: {
        charlotte: true,
        onremove: true,
        markimage: "image/card/handcard.png",
        intro: { content: "手牌上限+#" },
        mod: {
          maxHandcard(player, num) {
            return num + player.countMark("mogui_hand");
          }
        }
      }
    }
