    async content(event, trigger, player) {
      const bool = player.storage[event.name];
      const num = bool ? 3 : 2;
      await player.draw(num);
      if (!game.hasPlayer((current) => current !== player) || !player.hasCards("he")) {
        return;
      }
      const result = await player.chooseCardTarget({
        prompt: `仁诚：你可交给一名其他角色至多${get.cnNumber(num)}张牌`,
        position: "he",
        selectCard: [1, num],
        filterTarget: lib.filter.notMe,
        ai1(card) {
          return 7 - get.value(card);
        },
        ai2(target) {
          const player2 = get.player();
          let att = get.attitude(player2, target);
          if (target.hasSkillTag("nogain")) {
            att /= 10;
          }
          return att;
        }
      }).forResult();
      if (result?.bool && result.cards?.length && result.targets?.length) {
        const {
          targets: [target],
          cards: cards2
        } = result;
        player.line(target);
        await player.give(cards2, target);
        if (!bool) {
          return;
        }
        if (cards2.some((card) => get.type(card) === "basic")) {
          target.addSkill(`${event.name}_effect`);
        }
        if (cards2.some((card) => get.type2(card) === "trick") && game.hasPlayer((current) => current.hasDiscardableCards(player, "hej"))) {
          const result2 = await player.chooseTarget({
            prompt: "仁诚：你可以选择一名角色，然后弃置其区域内的一张牌",
            filterTarget(card, player2, target2) {
              return target2.hasDiscardableCards(player2, "hej");
            },
            ai(target2) {
              const player2 = get.player();
              return get.effect(target2, { name: "guohe_copy" }, player2, player2);
            }
          }).forResult();
          if (result2?.targets?.length) {
            const [target2] = result2.targets;
            player.line(target2);
            await player.discardPlayerCard(target2, "hej", true);
          }
        }
        if (cards2.some((card) => get.type(card) === "equip")) {
          await player.recover();
          await target.recover();
        }
      }
    },
