            if (!info2 || info2.charlotte || info2.juexingji || info2.hiddenSkill || info2.zhuSkill || info2.limited) {
              return false;
            }
            if (typeof info2.groupSkill === "string" && info2.groupSkill !== player.group) {
              return false;
            }
            if (info2.ai && (info2.ai.combo || info2.ai.notemp || info2.ai.neg)) {
              return false;
            }
            return !skillsx.includes(skill);
          }).map(
            /** @returns { [skill: string, owner: string] } */
            (skill) => [skill, name]
          )
        );
      }
      if (skills2.length) {
        const result = await player.chooseButton({
          createDialog: [`相谶：请选择一个技能获得`, [skills2.randomGets(3), "skill"]],
          forced: true,
          ai(button) {
            return get.skillRank(button.link, "inout");
          }
        }).forResult();
        if (result.links?.length) {
          await player.addAdditionalSkills(event.name, result.links, true);
        }
      } else {
        player.chat("天有不测风云啊");
      }
    },
    ai: {
      order: 8,
      result: {
        target(player, target) {
          if (target === player) {
            return Math.random() - 0.5;
          }
          const sgn = get.sgnAttitude(player, target);
          const name = target.name;
          const hp = get.character(name).hp;
          if (hp >= 3 && hp <= 5) {
            return sgn * (Math.random() + 1);
          }
          return sgn * Math.random();
        }
      }
    },
    group: ["dcxiangchen_changeHp", "dcxiangchen_clear"],
    subSkill: {
      changeHp: {
        audio: "dcxiangchen",
