xianding:dcjichao.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event, player) {
      return game.hasPlayer((current) => current !== player && current.countCards("he") > 0);
    },
    chooseButton: {
      dialog(event, player) {
        const choiceList = [
          ["one", "令一名其他角色将随机一半手牌（向上取整）和装备区的牌置于武将牌上"],
          ["all", "令所有其他角色将所有牌置于武将牌上"]
        ];
        const dialog = ui.create.dialog("激潮", [choiceList, "textbutton"], "hidden");
        dialog.direct = true;
        return dialog;
      },
      filter(button, player) {
        return button.link === "one" || !player.hasSkill("dcjichao_blocker");
      },
      check(button) {
        get.player();
        if (button.link === "all") {
          return 2;
        }
        return 1;
      },
      backup(links, player) {
        return {
          audio: "dcjichao",
          choice: links[0],
          manualConfirm: true,
          filterTarget(card, player2, target) {
            return target !== player2 && target.countCards("he") > 0;
          },
          selectTarget() {
            const { choice } = get.info("dcjichao_backup");
            if (choice === "all") {
              return -1;
            }
            return 1;
          },
          multitarget: true,
          multiline: true,
          async content(event, trigger, player2) {
            const { targets, name } = event;
            const { choice } = get.info(name);
            if (choice === "all") {
              player2.addTempSkill("dcjichao_blocker", { player: "dieAfter" });
            }
            const getCards = function(target) {
              let cards2 = target.getCards("h");
              if (choice !== "all") {
                const num = Math.ceil(cards2.length / 2);
                if (num > 0) {
                  cards2 = cards2.randomGets(num);
                }
              }
              cards2 = [...cards2, ...target.getCards("e")];
              return cards2;
            };
            if (choice === "all") {
              await game.loseAsync({
                lose_list: targets.sortBySeat().map((target) => [target, getCards(target)]),
                player: player2,
                log: true,
                animate: "giveAuto",
                gaintag: ["dccangming"]
              }).setContent("addToExpansionMultiple");
            } else {
              const [target] = targets;
              const next = target.addToExpansion(getCards(target), target, "giveAuto");
              next.gaintag.add("dccangming");
              await next;
            }
          },
          ai1: () => 1,
          ai2(target) {
            const player2 = get.player();
            return -get.attitude(player2, target);
          }
        };
      },
      prompt(links, player) {
        if (links[0] === "all") {
          return "令所有其他角色将所有牌置于武将牌上，称为“溟”";
        }
        return "令一名其他角色将随机一半手牌（向上取整）和装备区的牌置于武将牌上，称为“溟”";
      }
    },
    ai: {
      order(item, player) {
        player ??= get.player();
        if (game.hasPlayer((current) => {
          if (current === player || !current.countCards("h")) {
            return false;
          }
          if (get.attitude(player, current) > 0) {
            return false;
          }
          return player.countCards("hs", (card) => player.canUse(card, current) && get.effect(current, card, player, player) > 0) > 0;
        })) {
          return 9;
        }
        return 1;
      },
      result: {
        player(player, target) {
          if (game.hasPlayer((current) => {
            if (current === player || !current.countCards("h")) {
              return false;
            }
            return get.attitude(player, current) < 0;
          })) {
            return 1;
          }
          return 0;
        }
      }
    },
    subSkill: {
      blocker: {
        charlotte: true,
        silent: true,
        init(player, skill) {
          player.addMark(skill, 3, false);
        },
        onremove: true,
        intro: {
          content: "还需造成#点伤害"
        },
        trigger: {
          source: "damage"
        },
        filter(event, player) {
          return event.num > 0;
        },
        async content(event, trigger, player) {
          const { num } = trigger;
          player.removeMark(event.name, num, false);
          if (!player.hasMark(event.name)) {
            player.removeSkill(event.name);
          }
        }
      },
      backup: {}
    }
  }

