          if (button.link === "fengyin") {
            return 1.5;
          } else if (button.link === "judge") {
            return 1;
          } else if (button.link === "discard") {
            return 3;
          } else if (button.link === "use") {
            return 4;
          } else if (button.link === "gain") {
            return 8;
          }
