        for (const target of targets) {
          target.addTempSkill("dclishi_gain", { player: "phaseDiscardAfter" });
          target.markAuto("dclishi_gain", player);
        }
      }
    },
    subSkill: {
      gain: {
        trigger: {
          player: ["loseAfter"],
          global: ["loseAsyncAfter"]
        },
