        event.set(
          "zhuangpo_cards",
          event.player.getCards("hes", (card) => {
            if (get.name(card, event.player) === "sha") {
              return true;
            }
            const str = get.cardDescription(card, event.player);
            return str.includes("【杀】");
          })
        );
      }
    },
    viewAs: {
      name: "juedou",
      storage: { zhuangpo: true }
    },
    viewAsFilter() {
      return get.event().zhuangpo_cards?.length;
    },
    prompt: "将一张牌面信息包含“【杀】”的牌当【决斗】使用",
    filterCard(card, player) {
      return get.event().zhuangpo_cards.includes(card);
    },
    position: "hes",
    async precontent(event, trigger, player) {
      player.addTempSkill("zhuangpo_effect");
    },
    subSkill: {
      effect: {
        audio: "zhuangpo",
        trigger: { player: "useCardToPlayered" },
        filter(event, player) {
          const card = event.card;
          if (!card?.storage?.zhuangpo) {
            return false;
          }
          return player.hasMark("zhengqing");
        },
        charlotte: true,
        group: "zhuangpo_damage",
        async cost(event, trigger, player) {
          const target = trigger.target;
          const count = player.countMark("zhengqing");
          const prompt = `###壮魄：是否移去任意枚“擎”？###若如此做，${get.translation(target)}须弃置等量的牌`;
          const numbers = [{ prompt: "请选择要移去的“擎”", min: 1, max: count }];
          const next = player.chooseNumbers(prompt, numbers);
          next.set("processAI", () => {
            const { player: player2, target: target2 } = get.event();
            if (get.attitude(player2, target2) >= 0) {
              return false;
            }
            const markCount = player2.countMark("zhengqing");
            const cards2 = target2.getCards("he", (card) => lib.filter.cardDiscardable(card, target2));
            let allIn = false;
            if (player2.hp < 2 || target2.hp + target2.countCards("h", (card) => target2.canSaveCard(card, target2)) <= 1 + get.event().getTrigger().targets.some((current) => current.hasMark("zhengqing"))) {
              allIn = true;
            }
            if (cards2.map((card) => get.value(card)).reduce((p, c) => p + c, 0) / cards2.length > 5) {
              allIn = true;
            }
            if (!player2.isPhaseUsing() || !player2.hasCard((card) => {
              if (!get.cardDescription(card, player2).includes("【杀】")) {
                return false;
              }
              return player2.hasValueTarget(get.autoViewAs({ name: "juedou" }, [card]));
            })) {
              allIn = true;
            }
            const maxCount = Math.min(markCount, cards2.length);
            const toRemoveCount = allIn ? maxCount : Math.ceil(Math.random() * maxCount);
            return [toRemoveCount];
          }).set("target", target);
          const result = await next.forResult();
          event.result = {
            bool: typeof result?.numbers?.[0] === "number",
            cost_data: result?.numbers?.[0]
          };
        },
        logTarget: "target",
        async content(event, trigger, player) {
          const { targets, cost_data: toRemoveCount } = event;
          const [target] = targets;
          player.popup(`${get.cnNumber(toRemoveCount)}张`);
          player.removeMark("zhengqing", toRemoveCount);
          await target.chooseToDiscard("he", toRemoveCount, true, `${get.translation(player)}对你发动了【争擎】`, `你须弃置${get.cnNumber(toRemoveCount)}张牌`);
        }
      },
      damage: {
        audio: "zhuangpo",
        trigger: { global: "damageBegin1" },
        filter(event, player) {
          const card = event.card;
          if (!card?.storage?.zhuangpo) {
            return false;
          }
          const evt = event.getParent(2);
          return (evt.targets || []).some((current) => current.hasMark("zhengqing"));
        },
        charlotte: true,
        forced: true,
        async content(event, trigger, player) {
          await player.draw();
          trigger.num++;
        }
      }
    }
  }

xianding:dctuoyu.code:
{
    audio: 2,
    trigger: { player: ["phaseUseBegin", "phaseUseEnd"] },
    filter(event, player) {
      return player.countCards("h") > 0 && player.getStorage("dctuoyu").length > 0;
    },
    forced: true,
    async content(event, trigger, player) {
      const hs = player.getCards("h");
      const tags = ["dctuoyu_fengtian", "dctuoyu_qingqu", "dctuoyu_junshan"];
      const storage = player.getStorage("dctuoyu");
      let list = [
        ["未分配手牌", []],
        [`${get.translation(`${tags[0]}_tag`)}<div class="text center">伤害/回复值+1</div>`, []],
        [`${get.translation(`${tags[1]}_tag`)}<div class="text center">无次数和距离限制</div>`, []],
        [`${get.translation(`${tags[2]}_tag`)}<div class="text center">不可被响应</div>`, []]
      ];
      for (const card of hs) {
        let added = false;
        for (let i = 0; i < tags.length; i++) {
          if (card.hasGaintag(`${tags[i]}_tag`)) {
            added = true;
            list[i + 1][1].push(card);
            break;
          }
        }
        if (!added) {
          list[0][1].push(card);
        }
      }
      for (let i = 0; i < tags.length; i++) {
        if (!storage.includes(tags[i])) {
          list[i + 1][0] = `${get.translation(`${tags[i]}_tag`)}<div class="text center">尚未激活</div>`;
        }
      }
      list = [list[0], list.slice(1)];
      const next = player.chooseToMove_new("拓域：请分配你的手牌", true);
      next.set("list", list);
      next.set("filterMove", (from, to, moved) => {
        const player2 = _status.event.player;
        const storage2 = player2.getStorage("dctuoyu");
        const tags2 = ["dctuoyu_fengtian", "dctuoyu_qingqu", "dctuoyu_junshan"];
        if (typeof to === "number") {
          if (to === 0) {
            return true;
          }
          return storage2.includes(tags2[to - 1]) && moved[to].length < 5;
        }
        return true;
      });
      next.set("processAI", () => {
        const player2 = _status.event.player;
        const storage2 = player2.getStorage("dctuoyu");
        const tags2 = ["dctuoyu_fengtian", "dctuoyu_qingqu", "dctuoyu_junshan"];
        const moved = [[], [], [], []];
        const isEmpty = function(to) {
          return storage2.includes(tags2[to - 1]) && moved[to].length < 5;
        };
        const hs2 = player2.getCards("h");
        const hs22 = hs2.slice(0);
        let usable = player2.getCardUsable("sha");
        const addTo = function(card, to) {
          if (isEmpty(to)) {
            hs22.remove(card);
            moved[to].push(card);
            if (get.name(card) === "sha" && to !== 2) {
              usable--;
            }
          }
        };
        const hasRuanshizi = game.hasPlayer((target) => {
          return target !== player2 && player2.canUse("sha", target, null, true) && !target.mayHaveShan(player2, "use") && get.attitude(player2, target) < 0 && get.effect(target, { name: "sha" }, player2, player2) > 0;
        });
        for (const card of hs2) {
          const name = get.name(card);
          if (name === "tao" || name === "jiu") {
            addTo(card, 1);
          } else if (name === "sha") {
            if (hasRuanshizi && isEmpty(1) && usable > 0) {
              addTo(card, 1);
            } else if (isEmpty(3) && usable > 0) {
              addTo(card, 3);
            } else {
              addTo(card, 2);
            }
          } else if (get.type(name) === "trick") {
            if (isEmpty(1) && get.tag(card, "damage") > 0 && player2.hasUseTarget(card)) {
              addTo(card, 1);
            } else {
              addTo(card, 3);
            }
          }
        }
        moved[0].addArray(hs22);
        return moved;
      });
      const result = await next.forResult();
      if (result.bool) {
        game.broadcastAll(
          (moved, player2) => {
            if (player2 === game.me) {
              const cards2 = moved.flat(1).reverse();
              game.addVideo("lose", game.me, [get.cardsInfo(cards2), [], [], []]);
              for (let i = 0; i < cards2.length; i++) {
                cards2[i].goto(ui.special);
              }
              game.me.directgain(cards2, false);
            }
            const tags2 = ["dctuoyu_fengtian", "dctuoyu_qingqu", "dctuoyu_junshan"];
            const map = {};
            for (let i = 0; i < moved.length; i++) {
              for (const card of moved[i]) {
                for (let j = 0; j < tags2.length; j++) {
                  const tag = `${tags2[j]}_tag`;
                  const glowClass = `dctuoyu-${tags2[j].replace("dctuoyu_", "")}-glow`;
                  if (!map[tag]) {
                    map[tag] = [[], []];
                  }
                  if (i === j + 1) {
                    map[tag][0].add(card);
                    if (!card.hasGaintag(tag)) {
                      card.addGaintag(tag);
                      card.classList.add(glowClass);
                    }
                  } else {
                    if (card.hasGaintag(tag)) {
                      map[tag][1].add(card);
                      card.removeGaintag(tag);
                      card.classList.remove(glowClass);
                    }
                  }
                }
              }
            }
            for (const tag in map) {
              if (map[tag][0].length) {
                game.addVideo("addGaintag", player2, [get.cardsInfo(map[tag][0]), tag]);
