xianding:dczhuitao.code:
{
    audio: 2,
    comboSkill: true,
    mod: {
      aiOrder(player, card, num) {
        if (typeof card === "object") {
          const evt = lib.skill.dcjianying.getLastUsed(player);
          if (evt?.card && get.color(evt.card) === "black" && !evt.dczhuitao && get.is.damageCard(card)) {
            return num + 10;
          }
        }
      }
    },
    locked: false,
    trigger: { player: "useCard" },
    filter(event, player) {
      const { card } = event;
      if (!get.is.damageCard(card)) {
        return false;
      }
      const evt = lib.skill.dcjianying.getLastUsed(player, event);
      if (!evt || !evt.card || evt.dczhuitao) {
        return false;
      }
      return get.color(evt.card) === "black" && game.hasPlayer((target) => target !== player && !player.getStorage("dczhuitao_effect").includes(target));
    },
    async cost(event, trigger, player) {
      event.result = await player.chooseTarget(get.prompt2(event.skill), (card, player2, target) => {
        return target !== player2 && !player2.getStorage("dczhuitao_effect").includes(target);
      }).set("ai", (target) => {
        get.player();
      }).forResult();
    },
    async content(event, trigger, player) {
      trigger.set(event.name, true);
      const {
        targets: [target]
      } = event;
      player.addTempSkill(`${event.name}_effect`);
      player.markAuto(`${event.name}_effect`, target);
      await player.draw(2);
    },
    init(player, skill) {
      player.addSkill(`${skill}_mark`);
    },
    onremove(player, skill) {
      player.removeSkill(`${skill}_mark`);
    },
    subSkill: {
      effect: {
        audio: "dczhuitao",
        charlotte: true,
        onremove: true,
        mod: {
          globalFrom(from, to) {
            if (from.getStorage("dczhuitao_effect").includes(to)) {
              return -Infinity;
            }
          }
        },
        trigger: { player: "useCardAfter" },
        getIndex(event, player) {
          return event.targets.filter((target) => player.getStorage("dczhuitao_effect").includes(target)).sortBySeat();
        },
        filter(event, player, name, target) {
          const { card } = event;
          return get.info("dczhuitao_effect").getNum(card) > 0 && target.isIn() && target.countDiscardableCards(player, "he") > 0;
        },
        logTarget(event, player, name, target) {
          return target;
        },
        getNum(card) {
          return [(card2) => get.color(card2) === "black", (card2) => get.is.damageCard(card2)].filter((func) => func(card)).length;
        },
        prompt2(event, player) {
          return `弃置其至多${get.cnNumber(get.info("dczhuitao_effect").getNum(event.card))}张牌`;
        },
        check(event, player, name, target) {
          return get.effect(target, { name: "guohe_copy2" }, player, player);
        },
        async content(event, trigger, player) {
          const {
            targets: [target]
          } = event;
          const num = get.info(event.name).getNum(trigger.card);
          await player.discardPlayerCard(target, "he", [1, num], true);
        },
        intro: {
          content: "已选择过：$"
        }
      },
      mark: {
        init(player, skill) {
          const evt = lib.skill.dcjianying.getLastUsed(player);
          if (evt?.card && get.color(evt.card) === "black" && !evt.dczhuitao) {
            player.addTip(skill, "追讨 可连击");
          }
        },
        onremove(player, skill) {
          player.removeTip(skill);
        },
        charlotte: true,
        trigger: { player: ["useCard1", "useCardAfter"] },
        forced: true,
        popup: false,
        firstDo: true,
        async content(event, trigger, player) {
          if (event.triggername === "useCard1") {
            if (get.color(trigger.card) === "black") {
              player.addTip(event.name, "追讨 可连击");
            } else {
              player.removeTip(event.name);
            }
          } else if (trigger.dczhuitao) {
            player.removeTip(event.name);
          }
        }
      }
    }
  }

xianding:dcliexiang.code:
{
    audio: 2,
    enable: "phaseUse",
    usable(skill, player) {
      return player.hasSkill(`${skill}_extra`, null, null, false) ? 2 : 1;
    },
    chooseButton: {
      dialog(event, player) {
        return ui.create.dialog(`烈骧：你可以摸至多五张牌`, "hidden");
      },
      chooseControl(event, player) {
        const num = 5;
        const choices = [...Array.from(Array(num)).map((v, i) => `${get.cnNumber(i + 1)}张`), "cancel2"];
        return choices;
      },
      check() {
        const player = get.player();
        const hand = player.countCards("h");
        const hp = player.hp + player.countCards("hs", (card) => player.canSaveCard(card, player));
        const max = 5;
        let best = 5;
        let bestScore = -Infinity;
        for (let i = 1; i <= max; i++) {
          const num1 = hand + i;
          let score = 0;
          game.filterPlayer((current) => current !== player).forEach((target) => {
            const att = get.attitude(player, target);
            const num2 = target.countCards("h");
            score += get.damageEffect(target, player, player);
            if (num1 < num2) {
              if (player.hasSkill("dcliexiang_extra", null, null, false)) {
                score += i * get.effect(player, { name: "losehp" }, player, player) * 1.1;
              } else {
                if (i < hp) {
                  const diff = num2 - num1;
                  if (diff === 1) {
                    score += 100;
                  } else {
                    score += 40 - diff;
                  }
                  score -= i * 5;
                }
              }
            } else if (num1 === num2 && att < 0) {
              score += 30 + i * 2 + get.effect(target, { name: "shunshou_copy2" }, player, player);
            } else {
              score += 50 + i * 2;
            }
          });
          if (score > bestScore) {
            bestScore = score;
            best = i;
          }
        }
        best = Math.max(1, best);
        return best - 1;
      },
      prompt(result, player) {
        const num = result.index + 1;
        const prompt = get.skillInfoTranslation("dcliexiang", player);
        const draw = `摸${get.cnNumber(num)}张牌`;
        return `###烈骧###${prompt.replace("出牌阶段限一次，你可以摸至多五张牌", draw)}`;
      },
      backup(result, player) {
        const info2 = get.copy(lib.skill["dcliexiang_backup"]);
        info2.index = result.index;
        return info2;
      }
    },
    ai: {
      order(item, player) {
        if (player.hasSkill("dcliexiang_extra", null, null, false)) {
          return get.order({ name: "sha" }) + 0.1;
        }
        return get.order({ name: "sha" }) - 0.1;
      },
      result: {
        player(player) {
          const num = player.countCards("h");
          const bool = game.hasPlayer((current) => {
            if (current === player) {
              return false;
            }
            const num2 = current.countCards("h");
            return num + 5 >= num2;
          });
          return bool ? 1 : 0;
        }
      }
    },
    subSkill: {
      backup: {
        audio: "dcliexiang",
        manualConfirm: true,
        async content(event, trigger, player) {
          const { index } = get.info(event.name);
          await player.draw(index + 1);
          if (!game.hasPlayer((current) => current !== player)) {
            return;
          }
          const max = player.countMark("dcliexiang_extra") + 1;
          const result = await player.chooseTarget(lib.filter.notMe, [1, max], true).set("prompt", `烈骧：请选择${max > 1 ? "至多" : ""}${get.cnNumber(max)}名其他角色`).set("prompt2", "这些角色按照你选择的顺序依次执行：{你对其造成1点伤害，然后若你的手牌数：1.大于其，本回合你出【杀】次数+1且你可以交给一名其他角色至多X张牌；2.等于其，你获得其一张牌且其下回合使用的前X张牌无效；3.小于其，你失去X点体力，此技能本回合修改为“出牌阶段限两次”且可额外选择至多X名其他角色（X为你选择的摸牌数）。}。").set("multitarget", true).set("targetprompt", (target) => {
            const num = ui.selected.targets.length;
            return `第${num}个结算`;
          }).set("ai", (target) => {
            const { player: player2, numx, drawNum } = get.event();
            const num = target.countCards("h");
            const hp = player2.hp + player2.countCards("hs", (card) => player2.canSaveCard(card, player2));
            if (!player2.hasSkill("dcliexiang_extra", null, null, false) && !ui.selected.targets.length) {
              let score = 0;
              const att = get.attitude(player2, target);
              score += get.damageEffect(target, player2, player2);
              if (numx < num) {
                if (drawNum < hp) {
                  const diff = num - numx;
                  if (diff === 1) {
                    score += 100;
                  } else {
                    score += 40 - diff;
                  }
                  score -= drawNum * 5;
                }
              } else if (numx === num && att < 0) {
                score += 30 + drawNum * 2 + get.effect(target, { name: "shunshou_copy2" }, player2, player2);
              } else {
                score += 50 + drawNum * 2;
              }
              return score;
            } else {
              const eff = get.damageEffect(target, player2, player2);
              if (numx > num) {
                return eff + 10;
              } else if (numx === num) {
                return get.effect(target, { name: "shunshou_copy2" }, player2, player2) + eff;
              } else {
                if (player2.hasSkill("dcliexiang_extra") || hp <= (1 + ui.selected.targets.filter((current) => current.countCards("h") > numx).length) * drawNum) {
                  return 0;
                }
                return eff;
              }
            }
          }).set("drawNum", index + 1).set("numx", player.countCards("h")).forResult();
          if (!result?.bool || !result.targets?.length) {
            return;
          }
          const func = async (target) => {
            await target.damage();
            const num = player.countCards("h") - target.countCards("h");
            if (num > 0) {
              const skill = "dcliexiang_effect";
              player.addTempSkill(skill);
              player.addMark(skill, 1, false);
              if (player.hasCards("he") && game.hasPlayer((current) => current !== player)) {
                const result2 = await player.chooseCardTarget({
                  prompt: `烈骧：你可以将至多${get.cnNumber(index + 1)}张牌交给其他角色`,
                  filterCard: true,
                  position: "he",
                  selectCard: [1, index + 1],
                  filterTarget: lib.filter.notMe,
                  ai1(card) {
                    return 1 / Math.max(0.1, get.value(card));
                  },
                  ai2(target2) {
                    const player2 = get.player();
                    let att = get.attitude(player2, target2);
                    if (target2.hasSkillTag("nogain")) {
                      att /= 9;
                    }
                    return att;
                  },
                  allowChooseAll: true
                }).forResult();
                if (result2?.cards?.length && result2.targets?.length) {
                  const {
                    targets: [target2],
                    cards: cards2
                  } = result2;
                  player.line(target2);
                  await player.give(cards2, target2);
                }
              }
            }
            if (num === 0) {
              const numx = target.countGainableCards(player, "he");
              if (numx > 0) {
                await player.gainPlayerCard(target, "he", true);
              }
              target.addTempSkill("dcliexiang_debuff", { player: "phaseAfter" });
              if (index + 1 > target.countMark("dcliexiang_debuff")) {
                target.setMark("dcliexiang_debuff", index + 1, false);
              }
            }
            if (num < 0) {
              await player.loseHp(index + 1);
              if (player.hasSkill("dcliexiang", null, null, false)) {
                player.addTempSkill("dcliexiang_extra");
                player.setMark("dcliexiang_extra", index + 1, false);
              }
            }
          };
          player.line(result.targets);
          await game.doAsyncInOrder(result.targets, func, () => 0);
        }
      },
      debuff: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "下个回合使用的前#张牌无效"
        },
        forced: true,
        popup: false,
        trigger: { player: "useCard" },
        filter(event, player) {
          return _status.currentPhase === player && player.hasMark("dcliexiang_debuff");
        },
        async content(event, trigger, player) {
          player.removeMark(event.name, 1, false);
          if (!player.hasMark(event.name)) {
            player.removeSkill(event.name);
          }
          game.log(trigger.card, "被无效了");
          player.popup("无效");
          trigger.all_excluded = true;
        }
      },
      extra: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "改为出牌阶段限两次，且可额外选择至多#个目标"
        }
      },
      effect: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "出杀次数+#"
        },
        mod: {
          cardUsable(card, player, num) {
            if (get.name(card) === "sha") {
              return num + player.countMark("dcliexiang_effect");
            }
          }
        }
      }
    }
  }

