          await target.recover();
          const result = await target.chooseBool(`###仁彀###是否令${get.translation(player)}发动一次至多摸两张牌的${get.poptip("dcliexiang")}？`).set(
            "choice",
            (() => {
              const num2 = player.countCards("h") + Math.min(
                2,
                game.countPlayer(() => true, true)
              );
              const bool = game.hasPlayer((current) => {
                if (current === player) {
                  return false;
                }
                const num22 = current.countCards("h");
                if (num22 < num2) {
                  return true;
                }
                return num22 === num2 && get.attitude(player, current) >= 0;
