xianding:dcsbmingfang.code:
{
    audio: 2,
    trigger: {
      player: ["phaseBegin", "phaseUseBegin"]
    },
    filter(event, player) {
      return game.hasPlayer((current) => {
        if (current === player) {
          return false;
        }
        if (event.name === "phase") {
          return current.countCards("h");
        }
        return player.canCompare(current);
      });
    },
    async cost(event, trigger, player) {
      if (trigger.name === "phase") {
        event.result = await player.chooseTarget(get.prompt(event.skill), "令一名其他角色展示一张手牌，此牌在其手牌中时其受到伤害+1", (card, player2, target) => {
          return player2 !== target && target.countCards("h");
        }).set("ai", (target) => {
          const player2 = get.player();
          return get.damageEffect(target, player2, player2);
        }).forResult();
        return;
