{
    audio: 2,
    trigger: {
      source: ["damageSource", "dieAfter"],
      player: ["phaseDrawBegin2"],
      global: "phaseBegin"
    },
    init(player, skill) {
      player.setStorage(skill, [0, 0, 0, 0]);
      player.addTip(skill, `${get.translation(skill)} ${player.getStorage(skill).join(" ")}`);
    },
    onremove(player, skill) {
      player.setStorage(skill, [0, 0, 0, 0]);
      player.removeTip(skill);
