          ],
          "textbutton"
        ]
      ]).set("filterButton", (button) => {
        const { player: player2, chosenList: list } = get.event();
        if (list.includes(button.link)) {
          return false;
        }
        return button.link !== "recover" || player2.isDamaged();
      }).set("chosenList", player.getStorage(`${event.skill}_used`)).set("ai", (button) => {
        const { player: player2 } = get.event();
        switch (button.link) {
          case "draw": {
            return get.effect(player2, { name: "draw" }, player2, player2);
          }
          case "recover": {
            return get.recoverEffect(player2);
          }
          default: {
            return 3 - player2.countCards("e");
          }
        }
      }).forResult();
      if (result?.bool && result.links?.length) {
        event.result = {
          bool: true,
          cost_data: result.links[0]
        };
      }
    },
    async content(event, trigger, player) {
      let num = 0;
      if (player.getHp() === 1) {
        num++;
      }
      ["e", "h"].forEach((pos) => {
