          num++;
        }
      });
      const { cost_data } = event;
      const name = `${event.name}_used`;
      player.addTempSkill(name);
      player.markAuto(name, cost_data);
      if (num <= 0) {
        return;
      }
      switch (cost_data) {
        case "draw": {
          await player.draw(num);
          break;
        }
        case "recover": {
          await player.recover(num);
          break;
        }
        default: {
          const cards2 = [];
          while (cards2.length < num) {
            let card = get.cardPile2((card2) => !cards2.includes(card2) && get.type(card2) === "equip" && player.canEquip(card2));
            if (!card) {
              card = get.cardPile2((card2) => !cards2.includes(card2) && get.type(card2) === "equip" && player.canEquip(card2, true));
            }
            if (card) {
              cards2.add(card);
              player.$gain2(card);
              await player.equip(card);
            } else {
              break;
            }
          }
          break;
        }
      }
