        game.log(player, "重置了", "#g【清政】");
        player.addGaintag(player.getCards("h"), event.name);
        player.addSkill("dcqingzheng_effect");
      }
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      },
      effect: {
        charlotte: true,
        onremove(player, skill) {
          player.removeGaintag("dcqingzheng");
        },
