{
    audio: 2,
    trigger: { target: "useCardToTargeted" },
    usable: 1,
    filter(event, player) {
      return event.player !== player;
    },
    check(event, player) {
      return true;
    },
    logTarget: "player",
    async content(event, trigger, player) {
      const target = event.targets[0];
      const targets = [player, target];
      await game.asyncDraw(targets, 2);
      if (!target.countCards("h") || !player.countCards("h")) {
        return;
      }
      const map = await game.chooseAnyOL(targets, get.info(event.name).chooseCard, [targets, player]).forResult();
      let card1;
      let card2;
      for (const target2 of targets) {
        if (target2 === player) {
          card1 = map.get(target2).cards[0];
        } else {
          card2 = map.get(target2).cards[0];
        }
      }
      if (!card1 || !card2) {
        return;
      }
      await player.swapHandcards(target, [card1], [card2]);
      const effect = "dcweiwei_effect";
      const tag = `dcweiwei_${player.playerid}`;
      game.addTempTag(tag, `维卫·${get.translation(player)}`);
      if (target.getCards("h").includes(card1)) {
        target.addGaintag([card1], tag);
      }
      player.addTempSkill(effect);
      player.markAuto(effect, [target]);
      player.when({
        global: "useCardAfter"
      }).filter((evt) => evt === trigger.getParent()).step(async (event2, trigger2, player2) => {
        if (!player2.getCards("h").includes(card2)) {
          return;
        }
        if (player2.hasUseTarget(card2)) {
          await player2.chooseUseTarget(card2);
        }
      });
    },
    chooseCard(player, targets, source, eventId) {
      const target = targets[0] === player ? targets[1] : targets[0];
      return player.chooseCard("h", true).set("prompt", `维卫：请选择一张要与${get.translation(target)}交换的手牌`).set("ai", (card) => {
        const { player: player2, target: target2, source: source2, att } = get.event();
        const useValue = target2.getUseValue(card);
        if (player2 === source2) {
          if (att > 0) {
            return useValue;
          }
          return 6 - get.value(card);
        }
        if (att > 0) {
          return (8 - get.value(card)) * useValue;
        }
        if (useValue === 0) {
          return 114514;
        }
        return 6 - get.value(card);
      }).set("target", target).set("source", source).set("att", get.attitude(player, target)).set("id", eventId).set("_global_waiting", true);
    },
    subSkill: {
      effect: {
        charlotte: true,
        onremove(player, skill) {
          for (const target of player.getStorage(skill)) {
            target.removeGaintag(`dcweiwei_${player.playerid}`);
          }
          delete player.storage[skill];
        },
        intro: { content: "本回合结束时，你可以对$中的手牌中仍有你因【维卫】交换给其的牌的角色造成1点伤害" },
        trigger: { global: "phaseEnd" },
        filter(event, player) {
          return player.getStorage("dcweiwei_effect").includes(event.player);
        },
        forced: true,
        popup: false,
        async content(event, trigger, player) {
          for (const target of player.getStorage(event.name).sortBySeat()) {
            if (!target.isIn()) {
              continue;
            }
            if (target.hasCards("h", (card) => card.hasGaintag(`dcweiwei_${player.playerid}`))) {
              const result = await player.chooseBool(`维卫：你可以对${get.translation(target)}造成1点伤害`).set("choice", get.damageEffect(target, player, player) > 0).forResult();
              if (result.bool) {
                await target.damage(player);
              }
            }
          }
          player.removeSkill(event.name);
        }
      }
    }
  }

