{
    audio: 2,
    comboSkill: true,
    mod: {
      aiOrder(player, card, num) {
        if (typeof card === "object") {
          const evt = lib.skill.dcjianying.getLastUsed(player);
          if (evt?.card && get.type(evt.card) === "equip" && !evt.dcjizhan && get.color(card, player) === "black") {
            return num + 10;
          }
        }
      }
    },
    trigger: {
      player: "useCard"
    },
    filter(event, player) {
      if (get.color(event.card) !== "black") {
        return false;
      }
      const evt = lib.skill.dcjianying.getLastUsed(player, event);
      if (!evt || !evt.card || evt.dcjizhan) {
        return false;
      }
      return get.type(evt.card) === "equip";
    },
    locked: false,
    async cost(event, trigger, player) {
      const num = player.getHistory("useSkill", (evt) => evt.skill === event.skill).length + 1;
      const result = await player.chooseButtonTarget({
        createDialog: [
          get.prompt2(event.skill),
          [
            [
              ["discard", `弃置其他角色共计至多${num}张牌`],
              ["damage", `对一名其他角色造成${num}点伤害，然后此技能本回合失效`]
            ],
            "textbutton"
          ]
        ],
        filterButton(button) {
          const player2 = get.player();
          if (button.link === "discard") {
            return game.hasPlayer((target) => target.countDiscardableCards(player2, "he") && player2 !== target);
          }
          return true;
        },
        filterTarget(card, player2, target) {
          const selected = ui.selected.buttons;
          if (!selected?.length || target === player2) {
            return false;
          }
          if (selected[0].link === "discard") {
            return target.hasDiscardableCards(player2, "he");
          }
          return true;
        },
        selectTarget() {
          const selected = ui.selected.buttons;
          if (!selected?.length) {
            return false;
          }
          if (selected[0].link === "discard") {
            return -1;
          }
          return 1;
        },
        num,
        complexSelect: true,
        ai1(button) {
          const player2 = get.player();
          if (button.link === "discard") {
            const list = game.filterPlayer((target) => target.countDiscardableCards(player2, "he")).map((target) => {
              const num2 = get.effect(target, { name: "guohe_copy2" }, player2, player2);
              return num2 ? num2 : 0;
            }).sort((a, b) => b - a);
            return list.slice(0, Math.min(get.event().num, list.length)).reduce((eff, num2) => eff + num2, 0);
          }
          if (player2.hasCards("h", (card) => player2.hasUseTarget(card) && get.type(card) === "equip" && player2.hasCards("he", (cardx) => player2.hasUseTarget(cardx) && get.color(cardx) === "black" && card !== cardx))) {
            return 1;
          }
          return Math.max(...game.filterPlayer().map((target) => get.damageEffect(target, player2, player2) * get.event().num));
        },
        ai2(target) {
          const selected = ui.selected.buttons;
          const player2 = get.player();
          if (selected[0].link === "discard") {
            return get.effect(target, { name: "guohe_copy2" }, player2, player2);
          }
          return get.damageEffect(target, player2, player2) * get.event().num;
        }
      }).forResult();
      if (result?.links?.length) {
        event.result = {
          bool: true,
          targets: result.links[0] === "discard" ? [] : result.targets ?? [],
          cost_data: result.links[0]
        };
      }
    },
    async content(event, trigger, player) {
      trigger.set(event.name, true);
      const choice = event.cost_data;
      let num = player.getHistory("useSkill", (evt) => evt.skill === event.name).length;
      if (choice === "discard") {
        if (_status.connectMode) {
          game.broadcastAll(() => {
            _status.noclearcountdown = true;
          });
        }
        const lose_list = [];
        while (num > 0) {
          const result = await player.chooseTarget("###极斩###", `弃置任意名其他角色累计至多${num}张牌`, (card, player2, target) => {
            return target.countDiscardableCards(player2, "he") && target !== player2;
          }).set("ai", (target) => {
            const player2 = _status.event.player;
            const discarded = _status.event.lose_list.find((item) => item[0] === target);
            if (discarded) {
