                return 0;
              }
              const num2 = discarded[1].length;
              if (num2 > 1 && player2.hp + player2.hujia > 2) {
                return 0;
              }
            }
            if (target === player2) {
              if (ui.cardPile.childNodes.length > 80 && player2.hasCard((card) => get.value(card) < 8)) {
                return 20;
              }
              return 0;
            }
            return get.effect(target, { name: "guohe_copy2" }, player2, player2);
          }).set("lose_list", lose_list).forResult();
          if (result.bool) {
