xianding:y_dc_falu.code:
{
    audio: "xinfu_falu",
    trigger: {
      player: "loseAfter",
      global: ["equipAfter", "addJudgeAfter", "gainAfter", "loseAsyncAfter", "addToExpansionAfter"]
    },
    forced: true,
    locked: false,
    filter(event, player) {
      return event.getl(player).hs.length > 0;
    },
    intro: {
      content(storage, player) {
        if (storage) {
          return `当前记录花色：${storage.map((i) => get.translation(i)).join("")}`;
        }
        return "未记录";
      }
    },
    async content(event, trigger, player) {
      const suits = trigger.getl(player).hs.map((i) => get.suit(i, player));
      let list = player.getStorage(event.name).concat(suits);
      if (list.length > 3) {
        list = list.slice(-3);
      }
      player.setStorage(event.name, list, true);
      const tip = player.getStorage(event.name).map((i) => get.translation(i)).join("");
      player.addTip(event.name, `法箓${tip}`);
      if (list.length < 3) {
        return;
      }
      if (list.toUniqued().length === 1) {
        const suit = list[0];
        player.setStorage(event.name, [], true);
        player.removeTip(event.name);
        const next = game.createEvent("removeFaluRecord", false);
        next.player = player;
        next.type = "same";
        next.suit = suit;
        next.setContent("emptyEvent");
        await next;
        const cards2 = [];
        while (true) {
          const card = get.cardPile2((card2) => {
            return cards2.every((cardx) => get.suit(cardx) !== get.suit(card2)) && get.suit(card2) !== suit;
          });
          if (card) {
            cards2.add(card);
          } else {
            break;
          }
        }
        if (cards2?.length) {
          await player.gain(cards2, "gain2");
        }
      }
      if (list.toUniqued().length === 3) {
        player.setStorage(event.name, [], true);
        player.removeTip(event.name);
        const next = game.createEvent("removeFaluRecord", false);
        next.player = player;
        next.type = "diff";
        next.setContent("emptyEvent");
        await next;
        const result = await player.chooseButtonTarget({
          createDialog: [
            "法箓：是否令一名角色失去或回复1点体力？",
            [
              [
                ["loseHp", "失去1点体力"],
                ["recover", "回复1点体力"]
              ],
              "tdnodes"
            ]
          ],
          filterTarget(card, player2, target2) {
            const buttons = ui.selected.buttons;
            if (!buttons?.length) {
              return false;
            }
            return buttons[0].link === "loseHp" || target2.isDamaged();
          },
          ai1(button) {
            const player2 = get.player();
            let eff1 = 0;
            let eff2 = 0;
            game.filterPlayer((current) => {
              const losehp = get.effect(current, { name: "losehp" }, current, player2);
              if (losehp > eff1) {
                eff1 = losehp;
              }
              const recover = get.recoverEffect(current, player2, player2);
              if (recover > eff2) {
                eff2 = recover;
              }
            });
            if (eff1 > eff2 && eff1 > 0) {
              return button.link === "loseHp" ? 1 : 0;
            }
            if (eff1 < eff2 && eff2 > 0) {
              return button.link === "loseHp" ? 0 : 1;
            }
            return 0;
          },
          ai2(target2) {
            const player2 = get.player();
            const buttons = ui.selected.buttons;
            if (!buttons?.length) {
              return false;
            }
            if (buttons[0].link === "loseHp") {
              return get.effect(target2, { name: "losehp" }, target2, player2);
            }
            return get.recoverEffect(target2, player2, player2);
          }
        }).forResult();
        if (!result?.bool) {
