xianding:dcjuanji.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event, player) {
      return player.getStorage("dcjuanji_used").length < 3 && event.juanji_record > 0;
    },
    onChooseToUse(event) {
      if (!game.online && !event.juanji_record) {
        const num = event.player.getStat("skill")["dcjuanji_backup"] ?? 0;
        event.set("juanji_record", num + 1);
      }
    },
    chooseButton: {
      dialog(event, player) {
        const dialog = ui.create.dialog("狷急");
        const num = event.juanji_record;
        const list = [
          ["damage", `令你与一名其他角色各回复${num}点体力，然后对你与其各造成${num}点伤害`],
          ["discard", `弃置至多${num}名其他角色各一张牌，然后你翻面`],
          ["draw", `摸${num}张牌，然后你弃置等量张牌`]
        ];
        dialog.add([list, "textbutton"]);
        dialog.direct = true;
        return dialog;
      },
      filter(button, player) {
        if (player.getStorage("dcjuanji_used").includes(button.link)) {
          return false;
        }
        return button.link === "draw" || game.hasPlayer((current) => {
          if (current === player) {
            return false;
          }
          return button.link === "damage" || current.countCards("he");
        });
      },
      check(button) {
        const player = get.player();
        const num = get.event().getParent().juanji_record;
        switch (button.link) {
          case "damage": {
            const eff = (current) => {
              const recover = Math.min(current.getDamagedHp(), num);
              return recover * get.recoverEffect(current, player, player) + num * get.damageEffect(current, player, player);
            };
            const target = game.filterPlayer().maxBy(
              (current) => eff(current),
              (current) => current !== player
            );
            if (player.hasSkill("dcrenshuang")) {
              const num2 = player.getHp(true) + Math.min(player.getDamagedHp(), num) - num;
              if (num2 === 1) {
                return 114514;
              } else if (num2 < 1 && player.countCards("hs", (card) => get.tag(card, "save")) > -num2) {
                return 0.3;
              }
            }
            if (!target) {
              return 0;
            }
            return eff(player) + eff(target);
          }
          case "discard": {
            const eff = (current) => get.effect(current, { name: "guohe_copy2" }, player, player);
            const discard = game.filterPlayer((current) => current !== player && eff(current) > 0).sort((a, b) => eff(a) - eff(b));
            const discard2 = discard.slice(0, Math.min(game.countPlayer(), num, discard.length)).reduce((sum, current) => sum + eff(current), 0);
            return discard2;
          }
          default: {
            return num * 0.4;
          }
        }
      },
      backup(links, player) {
        return {
          audio: "dcjuanji",
          numx: get.event().juanji_record,
          choice: links[0],
          damageCheck: (function() {
            if (player.hasSkill("dcrenshuang")) {
              const num = get.event().juanji_record;
              const num2 = player.getHp(true) + Math.min(player.getDamagedHp(), num) - num;
              if (num2 === 1 || num2 < 1 && player.countCards("hs", (card) => get.tag(card, "save")) > -num2) {
                return true;
              }
            }
            return false;
          })(),
          filterTarget(card, player2, target) {
            if (target === player2) {
              return false;
            }
            const { choice } = get.info("dcjuanji_backup");
            switch (choice) {
              case "damage": {
                return true;
              }
              case "discard": {
                return target.countCards("he");
              }
              default: {
                return false;
              }
            }
          },
          selectTarget() {
            const { choice, numx } = get.info("dcjuanji_backup");
            switch (choice) {
              case "damage": {
                return 1;
              }
              case "discard": {
                return [1, numx];
              }
              default: {
                return -1;
              }
            }
          },
          multiline: true,
          multitarget: true,
          async content(event, trigger, player2) {
            const { choice, numx } = get.info(event.name);
            player2.addTempSkill("dcjuanji_used", "phaseChange");
            player2.markAuto("dcjuanji_used", choice);
            switch (choice) {
              case "damage": {
                for (const method of ["recover", "damage"]) {
                  for (const current of [player2, ...event.targets]) {
                    if (current.isIn()) {
                      await current[method](numx);
                    }
                  }
                }
                break;
              }
              case "discard": {
                for (const target of event.targets) {
                  await player2.discardPlayerCard(target, "he", true);
                }
                await player2.turnOver();
                break;
              }
              default: {
                await player2.draw(numx);
                await player2.chooseToDiscard("he", numx, true);
                break;
              }
            }
          },
          ai1() {
            return 1;
          },
          ai2(target) {
            const { choice, numx, damageCheck } = get.info("dcjuanji_backup");
            const player2 = get.player();
            switch (choice) {
              case "damage": {
                const eff = (current) => {
                  const recover = Math.min(current.getDamagedHp(), numx);
                  return recover * get.recoverEffect(current, player2, player2) + numx * get.damageEffect(current, player2, player2);
                };
                if (damageCheck) {
                  return eff(target);
                }
                return eff(player2) + eff(target);
              }
              case "discard": {
                return get.effect(target, { name: "guohe_copy2" }, player2, player2);
              }
              default: {
                return 1;
              }
            }
          }
        };
      },
      prompt(links, player) {
        const { choice, numx: num } = get.info("dcjuanji_backup");
        switch (choice) {
          case "damage": {
            return `令你与一名其他角色各回复${num}点体力，然后对你与其各造成${num}点伤害`;
          }
          case "discard": {
            return `弃置至多${num}名其他角色各一张牌，然后你翻面`;
          }
          default: {
            return `摸${num}张牌，然后你弃置等量张牌`;
          }
        }
      }
    },
    ai: {
      order: 7,
      result: {
        player: 1
      }
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      },
      backup: {}
    }
  }

