      return index >= 1;
    },
    async cost(event, trigger, player) {
      const history = game.getAllGlobalHistory("useCard");
      const index = history.indexOf(trigger);
      if (index < 1) {
        return;
      }
      const bool1 = get.cardNameLength(trigger.card) === get.cardNameLength(history[index - 1].card);
      const bool2 = get.type2(trigger.card) === get.type2(history[index - 1].card);
      if (bool1 && bool2) {
        const result = await player.chooseControl({
          prompt: get.prompt2(event.skill),
          controls: ["摸两张牌", `令${get.translation(trigger.card)}不计入次数`],
          ai() {
            const { player: player2, controls } = get.event();
            const usable = player2.getCardUsable(get.event().getTrigger().card);
            if (usable <= 0) {
              return controls[1];
            }
            return controls[0];
          }
        }).forResult();
        if (typeof result?.control === "string") {
          event.result = {
            bool: true,
            cost_data: result.control
          };
        }
      } else if (!bool1 && !bool2) {
        event.result = {
          bool: true,
          cost_data: "tempBan"
        };
      }
    },
