            return false;
          }
          return lib.filter.filterCard.apply(this, arguments);
        },
        `${get.translation(event.name)}：是否对${get.translation(target)}使用一张手牌？`
      ).set("filterTarget", function(card, player2, target2) {
        const source2 = get.event().sourcex;
