        }
        return lib.filter.targetEnabled.apply(this, arguments);
      }).set("ai1", (card) => {
        const player2 = get.player();
        if (get.tag(card, "damage") && player2.hasValueTarget(card)) {
          return 10 + get.cacheOrder(card);
        }
        return get.cacheOrder(card);
      }).set("targetRequired", true).set("complexTarget", true).set("complexSelect", true).set("sourcex", target).set("addCount", false).forResult();
      if (result?.bool) {
        await player.draw(2);
      }
      if (!result?.bool || !source.hasHistory("sourceDamage", (evt) => evt.getParent(4) === event)) {
        const result2 = await player.chooseBool(`是否令${get.translation(source)}失去1点体力？`).set(
          "choice",
          (() => {
            return get.effect(source, { name: "losehp" }, player, player) > 0;
          })()
        ).forResult();
        if (result2?.bool) {
