        player(player, target) {
          if (!ui.selected.targets.length) {
            return Math.max(
              ...game.filterPlayer((current) => ![player, target].includes(current)).map((current) => {
                let sum2 = 0;
                const cards3 = target.getCards("h", (card) => target.canUse(card, current) && get.effect(current, card, target, target) > 0);
                if (cards3.length) {
                  cards3.sort((a, b) => get.effect(current, b, target, target) - get.effect(current, a, target, target));
                }
                if (cards3[0]) {
                  sum2 += get.effect(current, cards3[0], target, player);
                }
                if (!cards3[0] || !get.tag(cards3[0], "damage")) {
                  if (get.effect(target, { name: "losehp" }, player, player) > 0) {
                    sum2 += get.effect(target, { name: "losehp" }, player, player);
                  }
                  if (get.effect(player, { name: "draw" }, player, player) > 0) {
                    sum2 += get.effect(player, { name: "draw" }, player, player) * 2;
                  }
                }
                return sum2;
              })
            );
          }
          const source = ui.selected.targets[0];
          let sum = 0;
          const cards2 = source.getCards("h", (card) => source.canUse(card, target) && get.effect(target, card, source, source) > 0);
          if (cards2.length) {
            cards2.sort((a, b) => get.effect(target, b, source, source) - get.effect(target, a, source, source));
          }
          if (cards2[0]) {
            sum += get.effect(target, cards2[0], source, player);
          }
          if (!cards2[0] || !get.tag(cards2[0], "damage")) {
            if (get.effect(source, { name: "losehp" }, player, player) > 0) {
              sum += get.effect(source, { name: "losehp" }, player, player);
            }
            if (get.effect(player, { name: "draw" }, player, player) > 0) {
              sum += get.effect(player, { name: "draw" }, player, player) * 2;
            }
          }
          return sum;
        }
      }
    }
  }

