xianding:dcrejueyan.code:
{
    audio: "dcjueyan",
    trigger: { player: "useCardAfter" },
    filter(event, player) {
      if (player.getStorage("dcrejueyan_used").includes(get.type2(event.card))) {
        return false;
      }
      return event.targets?.length === 1;
    },
    async cost(event, trigger, player) {
      const storage = player.getStorage(event.skill, [1, 1, 1, false]);
      const list = ["摸牌", "拿牌", "拼点"];
      const choices = [list[0]];
      const choiceList = [`摸${get.cnNumber(storage[0])}张牌`, `随机从弃牌堆获得${get.cnNumber(storage[1])}张牌`, `与一名角色拼点，赢的角色对没赢的角色造成${storage[2]}点伤害`];
      if (Array.from(ui.discardPile.childNodes).length) {
        choices.add("拿牌");
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}（无法选择）</span>`;
      }
      if (game.hasPlayer((target) => player.canCompare(target))) {
        choices.add("拼点");
      } else {
        choiceList[2] = `<span style="opacity:0.5">${choiceList[2]}（无法选择）</span>`;
      }
      const { control: choice } = await player.chooseControl(choices, "cancel2").set("ai", () => {
        const player2 = get.player();
        const storage2 = player2.getStorage("dcrejueyan", [1, 1, 1, false]);
        const map = {
          摸牌: get.effect(player2, { name: "draw" }, player2, player2) * storage2[0],
          拿牌: get.effect(player2, { name: "draw" }, player2, player2) * Math.min(Array.from(ui.discardPile.childNodes).length, storage2[1]),
          拼点: Math.max(...[0].concat(game.filterPlayer((target) => player2.canCompare(target)).map((target) => get.effect(target, "hannan", player2, player2))))
        };
        return get.event().controls.slice().sort((a, b) => map[b] - map[a])[0];
      }).set("choiceList", choiceList).set("prompt", [get.prompt(event.skill), '<div class="text center">你可以选择一项执行，执行后该项目数值变为1，其余项目数值+1</div>'].map((str) => `###${str}`).join("")).forResult();
      if (!choice || choice === "cancel2") {
        event.result = { bool: false };
      } else {
        event.result = { bool: true, cost_data: list.indexOf(choice) };
      }
    },
    async content(event, trigger, player) {
      player.addTempSkill("dcrejueyan_used");
      player.markAuto("dcrejueyan_used", [get.type2(trigger.card)]);
      const storage = player.getStorage(event.name, [1, 1, 1, false]);
      const index = event.cost_data;
      switch (index) {
        case 0:
          await player.draw(storage[0]);
          break;
        case 1:
          await player.gain(Array.from(ui.discardPile.childNodes).randomGets(storage[1]));
          break;
        case 2: {
          const result = await player.chooseTarget(
            true,
            (card, player2, target) => {
              return player2.canCompare(target);
            },
            `与一名角色拼点，赢的角色对没赢的角色造成${storage[2]}点伤害`
          ).set("ai", (target) => {
            const player2 = get.player();
            return get.effect(target, "hannan", player2, player2);
          }).forResult();
          if (result?.bool && result.targets?.length) {
            const target = result.targets[0];
            const result2 = await player.chooseToCompare(target).forResult();
            if (result2) {
              if (!result2.tie) {
                const winner = result2.bool ? player : target;
                const loser = !result2.bool ? player : target;
                winner.line(loser);
                await loser.damage(storage[2], winner);
              }
            }
          }
          break;
        }
      }
      if (Array.isArray(player.storage[event.name])) {
        player.storage[event.name][index] = 1;
        const nums = Array.from({ length: 3 }).map((_, i) => i).filter((i) => i !== index);
        for (const num of nums) {
          if (player.storage[event.name][num] < 3) {
            player.storage[event.name][num]++;
          }
        }
        get.info(event.name).updateMark(player, event.name);
      }
    },
    init(player, skill) {
      player.storage[skill] = [1, 1, 1, false];
      get.info(skill).updateMark(player, skill);
    },
    onremove(player, skill) {
      player.removeTip(skill);
      delete player.storage[skill];
    },
    updateMark(player, skill) {
      player.markSkill(skill);
      player.addTip(skill, [get.translation(skill), ...player.storage[skill].slice(0, 3)].join(" "));
    },
    intro: {
      markcount: (storage) => storage.slice(0, 3).map((i) => i.toString()).join(""),
      content: (storage) => `当前选项数值为：${storage.slice(0, 3)}`
    },
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      }
