{
    audio: 2,
    trigger: { player: "damageEnd" },
    filter(event, player) {
      return event.num > 0;
    },
    getIndex: (event) => event.num,
    async cost(event, trigger, player) {
      event.result = player.chooseTarget(get.prompt2(event.skill)).set("ai", (target) => {
