      const storage = player.getStorage("dcyitong");
      const suits = lib.suit.filter((suit) => {
        if (name === "phaseBefore" || name === "enterGame") {
          return !storage.includes(suit);
        }
        if (!storage.includes(suit) || !trigger.getd?.().some((card) => get.suit(card, false) === suit)) {
          return false;
        }
        return game.getGlobalHistory("everything", (evt) => {
          if (evt.name !== "cardsDiscard") {
            return false;
          }
          const evtx = evt.getParent();
          if (evtx.name !== "orderingDiscard") {
            return false;
          }
          const evt2 = evtx.relatedEvent || evtx.getParent();
          if (evt2.name !== "useCard") {
            return false;
          }
          return evt.getd?.()?.some((card) => get.suit(card, false) === suit);
        }).indexOf(trigger) === 0;
      }).reverse();
      if (name === "phaseBefore" || name === "enterGame") {
        const result = suits.length > 1 ? await player.chooseControl(suits).set("ai", () => {
          return get.event().controls.randomGet();
        }).set("prompt", "异瞳：请记录一个花色").forResult() : { control: suits[0] };
        const suit = result.control;
        if (suit) {
          player.markAuto("dcyitong", [suit]);
          player.addTip("dcyitong", get.translation("dcyitong") + player.getStorage("dcyitong").reduce((str, suit2) => str + get.translation(suit2), ""));
        }
      } else {
        const gains = [];
        for (const suitx of suits) {
          for (const suit of lib.suit.slice().reverse()) {
            if (suitx === suit) {
              continue;
            }
            const card = get.cardPile((card2) => get.suit(card2) === suit && !gains.includes(card2));
            if (card) {
              gains.push(card);
            }
          }
        }
        if (gains.length) {
          await player.gain(gains, "gain2");
        }
      }
    },
    onremove(player, skill) {
      delete player.storage[skill];
      player.removeTip(skill);
    },
    intro: { content: "已记录$花色" }
  }

