{
    audio: 2,
    trigger: { player: "useCardAfter" },
    filter(event, player) {
      return get.type2(event.card) === "trick" && player.hasCard((card) => get.is.damageCard(card), "h");
    },
    frequent: true,
    async content(event, trigger, player) {
      const skill = "dcsblieji_effect";
      player.addTempSkill(skill);
      const cards2 = player.getCards("h", (card) => get.is.damageCard(card));
      for (const card of cards2) {
        let tag = card.gaintag?.find((tag2) => tag2.startsWith(skill));
        if (tag) {
          player.removeGaintag(tag, [card]);
        }
        tag = tag ? skill + parseFloat(parseInt(tag.slice(skill.length)) + 1) : "dcsblieji_effect1";
        game.addTempTag(tag, `烈计+${tag.slice(skill.length)}`);
        player.addGaintag([card], tag);
      }
    },
    subSkill: {
      effect: {
        audio: "dcsblieji",
        charlotte: true,
        onremove(player, skill) {
          let tags = player.getCards("h", (card) => card.gaintag?.some((tag) => tag.startsWith(skill)));
          if (tags.length) {
            tags = tags.slice().map((card) => card.gaintag.find((tag) => tag.startsWith(skill))).unique();
            tags.forEach((tag) => player.removeGaintag(tag));
          }
        },
        trigger: { player: "useCard" },
        filter(event, player) {
          if (!event.card) {
            return false;
          }
          return player.hasHistory(
            "lose",
            (evtx) => evtx.getParent() === event && Object.keys(evtx.gaintag_map).some((i) => {
              return evtx.gaintag_map[i].some((tag) => tag.startsWith("dcsblieji_effect"));
            })
          );
        },
        forced: true,
        logTarget: "player",
        async content(event, trigger, player) {
          const skill = event.name;
          const evt = trigger;
          const evtx = player.getHistory(
            "lose",
            (evtx2) => evtx2.getParent() === evt && Object.keys(evtx2.gaintag_map).some((i) => {
              return evtx2.gaintag_map[i].some((tag) => tag.startsWith(skill));
            })
          )[0];
          trigger.baseDamage += Object.keys(evtx.gaintag_map).reduce((sum, i) => {
            const tag = evtx.gaintag_map[i].find((tag2) => tag2.startsWith(skill));
            if (tag) {
              sum += parseInt(tag.slice(skill.length));
            }
            return sum;
          }, 0);
        }
      }
    }
  }

