{
    audio: 2,
    trigger: { player: "phaseJieshuBegin" },
    filter(event, player) {
      return player.hasCards("h");
    },
    async content(event, trigger, player) {
      const next = game.cardsGotoOrdering(get.cards(Math.min(5, player.countCards("h"))));
      await next;
      const cards2 = next.cards;
      await player.showCards(cards2, `${get.translation(player)}发动了〖撰文〗`);
      let result;
      result = !event.targets?.length ? await player.chooseTarget({
        prompt: get.prompt2(event.name),
        ai(target) {
          const { player: player2, cards: cards3 } = get.event();
          const damages = cards3.filter((card) => get.is.damageCard(card) && player2.canUse(card, target, false));
          cards3.filter((card) => !get.is.damageCard(card));
          if (damages.length > 1) {
            return -get.attitude(player2, target);
          }
          return get.attitude(player2, target);
        }
      }).set("cards", cards2).forResult() : { bool: true, targets: event.targets };
      if (result?.bool && result.targets?.length) {
        const target = result.targets[0];
        let damages = cards2.filter((card) => get.is.damageCard(card) && player.canUse(card, target, false));
        const nodamages = cards2.filter((card) => !get.is.damageCard(card));
        const list = [`依次对${get.translation(target)}使用${damages.length ? get.translation(damages) : "空气"}`, `令${get.translation(target)}获得${nodamages.length ? get.translation(nodamages) : "空气"}`];
        result = await player.chooseControl("使用伤害牌", "获得非伤害牌").set("choiceList", list).set("prompt", "撰文：请选择一项").set(
          "effect",
          (function() {
            let eff = 0;
            for (const card of damages) {
              eff += get.effect(target, card, player, player);
            }
            for (const card of nodamages) {
              eff -= get.value(card, target) * get.attitude(player, target);
            }
            return eff;
          })()
        ).set("ai", (event2, player2) => {
          if (get.event().effect > 0 || player2.hasStorage("dcsbyaozuo_effect", get.event().target)) {
            return "使用伤害牌";
          }
          return "获得非伤害牌";
        }).set("target", target).forResult();
        if (result?.control === "使用伤害牌") {
          while (damages.length) {
            const card = damages[0];
            if (player.canUse(card, target, false)) {
              await player.useCard(card, target, false);
            }
            cards2.remove(card);
            damages = damages.filter((cardx) => card !== cardx && player.canUse(cardx, target, false));
          }
        } else {
          cards2.removeArray(nodamages);
          if (nodamages.length) {
            await target.gain({ cards: nodamages, animate: "gain2" });
          }
        }
      }
      await game.cardsGotoPile(cards2.reverse(), "insert");
    }
  }

