{
    audio: 2,
    trigger: { player: ["phaseZhunbeiBegin", "dying"] },
    async cost(event, trigger, player) {
      const list = ["场上", "牌堆", "cancel2"];
      if (!game.hasPlayer((current) => {
        return current.countCards("ej");
      })) {
        list.remove("场上");
      }
      const { control } = await player.chooseControl(list, () => {
        const player2 = _status.event.player;
        let cards2 = game.filterPlayer().reduce((arr, current) => {
          if (current.countCards("ej")) {
            arr.addArray(current.getCards("ej"));
          }
          return arr;
        }, []).sort((a, b) => get.number(a, false) - get.number(b, false));
        if (!cards2.length) {
          return "牌堆";
        }
        if (player2.hp < 1 && get.number(cards2[0], false) > 1) {
          return "牌堆";
        }
        cards2 = cards2.filter((card) => get.number(card, false) === get.number(cards2[0], false));
        const valueCards = cards2.filter((card) => {
          const owner = get.owner(card);
          if (!owner) {
            return false;
          }
          let att = get.attitude(player2, owner);
          if (get.position(card) === "j" && (card.viewAs || card.name) === "xumou_jsrg") {
            att *= -1;
          }
          if (get.position(card) === "e" && get.equipValue(card, owner) > 0) {
            att *= -1;
          }
          return att > 0;
        });
        if (valueCards.length * 2 >= cards2.length) {
          return "场上";
        }
        return "牌堆";
      }).set("prompt", get.prompt2(event.skill)).forResult();
      event.result = {
        bool: control !== "cancel2",
        cost_data: control
      };
    },
    async content(event, trigger, player) {
      const control = event.cost_data;
      let num = 1;
      let card;
      if (control === "场上") {
        const cards2 = game.filterPlayer().reduce((arr, current) => {
          if (current.countCards("ej")) {
            arr.addArray(current.getCards("ej"));
          }
          return arr;
        }, []).sort((a, b) => get.number(a, false) - get.number(b, false));
        num = get.number(cards2[0], false);
        card = cards2.filter((card2) => get.number(card2, false) === num).randomGet();
      } else {
        while (num < 14) {
          const cardx = get.cardPile2((card2) => get.number(card2, false) === num);
          if (cardx) {
            card = cardx;
            break;
          } else {
            num++;
          }
        }
      }
      if (card) {
        await player.gain(card, get.owner(card) ? "give" : "gain2");
        if (num === 1) {
          player.tempBanSkill("dcchaozhen");
          await player.recover();
        }
      }
    }
  }

