    filter(event, player) {
      if (!game.hasPlayer((current) => {
        return current.countCards("h") && !player.getStorage("dclianjie_used").includes(current);
      }) || !player.hasHistory("lose", (evt) => {
        if ((evt.relatedEvent || evt.getParent()) !== event.getParent()) {
          return false;
        }
        return event.cards?.some((card) => (evt.hs || []).includes(card));
      }) || !player.countCards("h")) {
        return false;
      }
      const num = get.number(event.card, player);
      if (typeof num !== "number" || player.hasCard((card) => get.number(card, player) < num, "h")) {
        return false;
      }
      return event.isFirstTarget;
    },
    async cost(event, trigger, player) {
      event.result = await player.chooseTarget(get.prompt2(event.name.slice(0, -5)), (card, player2, target) => {
        return target.countCards("h") && !player2.getStorage("dclianjie_used").includes(target);
      }).set("ai", (target) => {
        const player2 = get.player();
        const eff1 = get.effect(target, { name: "guohe_copy2" }, player2, player2);
        const eff2 = get.effect(target, { name: "draw" }, player2, player2);
        if (player2 === target) {
          return eff2 * (1 + player2.maxHp - player2.countCards("h"));
        }
        return eff1;
      }).forResult();
    },
    async content(event, trigger, player) {
      get.number(trigger.card, player) || 0;
      const target = event.targets[0];
