            list.push(get.effect(target, { name: "guohe_copy", position: "h" }, target, player) * Math.sqrt(Math.min(2, target.countDiscardableCards(target, "h"))));
          }
          return list;
        })()
      ) > 0;
    },
    async content(event, trigger, player) {
      trigger.cancel();
      let result;
      const target = event.targets[0];
