        [
          `${get.translation(event.name)}：请选择你要执行的选项`,
          `<div class="text center">${lib.translate[`${event.name}_info`]}</div>`,
          [
            [
              "失去体力",
              ...Array.from({ length: 5 }).map((_, i) => {
                const sub = `equip${(i + 1).toString()}`;
