          attackRange(player, num) {
            return num + player.countMark("dcdufeng_effect");
          },
          cardUsable(card, player, num) {
            if (card.name === "sha") {
              return num + player.countMark("dcdufeng_effect");
            }
          }
        }
      }
    }
  }

