          if (!["dcsanshi", "dcchenlve"].every((skill) => player.hasSkill(skill, null, false, false))) {
            return false;
          }
          const cards2 = event.getg(player);
          if (!cards2.length) {
            return false;
          }
          return cards2.some((card) => card.storage.dcsanshi);
