        if (current.hasSkill("dcsbzijin")) {
          return false;
        }
        return current.countCards("h") > 0 && current !== player;
      });
    },
    derivation: "dcsbzijin",
    chooseButton: {
      dialog() {
        return ui.create.dialog("###讨州###请选择一个数字（对其他角色不可见）");
      },
      chooseControl(event, player) {
        const list = [1, 2, 3];
        list.push("cancel2");
        return list;
      },
      check() {
        const event = get.event();
        const player = get.player();
        if (game.hasPlayer((current) => {
          return current !== player && get.attitude(player, current) < 0;
        })) {
          return [0, 1, 2].randomGet();
        }
        if (player.hasShan()) {
          return 2;
        }
        const rand = event.getRand();
        if (rand < 0.2) {
          return 0;
        }
        if (rand < 0.5) {
          return 1;
        }
        return 2;
      },
      backup(result, player) {
        return {
          audio: "dcsbtaozhou",
          chosenNumber: result.index + 1,
          filterCard: () => false,
          selectCard: -1,
          filterTarget(card, player2, target) {
            return target.countCards("h") > 0 && target !== player2;
          },
          async content(event, trigger, player2) {
            const [target] = event.targets;
            const chosenNumber = get.info("dcsbtaozhou_backup").chosenNumber;
            const { cards: cards2 } = await target.chooseToGive(`${get.translation(player2)}对你发动了【讨州】`, "你可以交给其至多三张手牌", [1, 3], player2).set("ai", (card) => {
              if (get.event().att > 0) {
                if (get.event().chosenNumber < ui.selected.cards.length + (get.event().getRand() < 0.5)) {
                  return 5.1 - get.value(card);
                }
                return 0;
              }
              if (ui.selected.cards.length > 1) {
                return -get.value(card);
              }
              if (ui.selected.cards.length > 0) {
                return 3.6 - get.value(card);
              }
              return 4.6 - get.value(card);
            }).set("att", get.attitude(target, player2)).set("chosenNumber", chosenNumber).forResult();
            const givenCount = cards2 && cards2.length || 0;
            const delta = Math.abs(givenCount - chosenNumber);
            if (givenCount >= chosenNumber) {
              await game.asyncDraw([player2, target]);
            } else {
              target.addSkill("dcsbtaozhou_debuff");
              target.addMark("dcsbtaozhou_debuff", delta, false);
            }
            if (delta >= 2) {
              const sha = get.autoViewAs({ name: "sha" });
              if (target.canUse(sha, player2, false)) {
                await target.addSkills("dcsbzijin");
              }
            }
            const roundNumberToRestore = game.roundNumber + chosenNumber;
            player2.tempBanSkill("dcsbtaozhou", "forever");
            player2.when({ global: "roundStart" }, false).filter(() => {
              return game.roundNumber >= roundNumberToRestore;
            }).assign({
              firstDo: true
            }).step(async () => {
              delete player2.storage[`temp_ban_dcsbtaozhou`];
            }).finish();
          },
          ai: {
            result: {
              player: 0.5,
              target() {
                const chosenNumber = get.info("dcsbtaozhou_backup").chosenNumber;
                if (chosenNumber > 1) {
                  return -1;
                }
                return 0;
              }
            }
          }
        };
      },
      prompt: () => "请选择【讨州】的目标"
    },
    subSkill: {
