          return 5.5 - get.value(card);
        }).set("goon", get.effect(player, trigger.card, target, player) < 0).forResult();
      } else {
        result = await player.discardPlayerCard(`###${get.prompt(event.skill, target)}###<div class="text center">弃置其的一张牌，令${get.translation(trigger.card)}对你无效。</div>`, target, "he").set("chooseonly", true).set("ai", (button) => {
