          const count = game.countPlayer((current) => {
            return current.hasSkill("dcwuyou") && !current.hasSkill("dcwuyou_targeted");
          });
          return count > 1 ? 1 : -1;
        },
        check(card) {
          const player = get.player();
          const hasFriend = game.hasPlayer((current) => {
            return current.hasSkill("dcwuyou") && !current.hasSkill("dcwuyou_targeted") && get.attitude(player, current) > 0;
          });
          return (hasFriend ? 7 : 1) - get.value(card);
        },
        prompt() {
          const player = get.player();
          const list = game.filterPlayer((current) => {
            return current.hasSkill("dcwuyou") && !current.hasSkill("dcwuyou_targeted");
          });
          const list2 = list.filter((current) => current !== player);
          const moreThanOne = list.length > 1;
          const includesMe = list.includes(player);
          let str = "选择一张手牌，";
          if (includesMe) {
            str += `点击“确定”，${moreThanOne ? "或" : ""}`;
          }
          if (moreThanOne || !includesMe) {
            str += `将此牌交给${get.translation(list2)}${list2.length > 1 ? "中的一人" : ""}，`;
          }
          str += "然后执行后续效果。";
          return str;
        },
        discard: false,
        lose: false,
        delay: false,
        async content(event, trigger, player) {
          const { target } = event;
          target.addTempSkill("dcwuyou_targeted", "phaseUseAfter");
          const isMe = target === player;
          let { cards: cards2 } = event;
          if (!isMe) {
            await player.give(cards2, target);
          }
          const names = lib.inpile.filter((name) => {
            return get.type2(name) !== "equip";
          }).randomGets(5);
          if (names.includes("sha")) {
            const natures = lib.inpile_nature.slice(0);
            natures.unshift(null);
            names[names.indexOf("sha")] = ["sha", natures.randomGet()];
          }
          const vcard = names.map((namex) => {
            let name = namex;
            let nature;
            if (Array.isArray(namex)) {
              [name, nature] = namex;
            }
            const info2 = [get.type(name), "", name, nature];
            return info2;
          });
          const str = `###武佑：你可以选择一个牌名###<div class='text center'>${isMe ? `令${get.translation(cards2)}视为你选择牌名的牌且无距离和次数限制` : `然后交给${get.translation(player)}一张手牌，此牌视为你选择牌名的牌且无距离和次数限制`}</div>`;
          const next = target.chooseButton([str, [vcard, "vcard"]]).set("user", player).set("ai", (button) => {
            const player2 = get.player();
            const user = get.event().user;
            return user.getUseValue({ name: button.link[2], nature: button.link[3] }) * get.attitude(player2, user);
          });
          const result = await next.forResult();
          if (!result?.links?.length) {
            return;
          }
          const { links } = result;
          const viewAs = { name: links[0][2], nature: links[0][3] };
          if (!isMe) {
            cards2 = (await target.chooseToGive(player).set("ai", (card2) => {
              const player2 = get.event().player;
              const target2 = get.event().getParent().player;
              if (get.attitude(player2, target2) <= 0) {
                return 0;
              }
              return 6 - get.value(card2);
            }).forResult())?.cards;
          }
          if (!cards2) {
            return;
          }
          const card = cards2[0];
          if (player.getCards("h").includes(card)) {
            if (!player.storage.dcwuyou_transfer) {
              player.storage.dcwuyou_transfer = {};
            }
            player.storage.dcwuyou_transfer[card.cardid] = viewAs;
            player.addGaintag(cards2, "dcwuyou_transfer");
            player.addSkill("dcwuyou_transfer");
          }
        },
        ai: {
          order: 10,
          result: {
            player(player, target) {
              if (get.attitude(player, target) > 0) {
                return 1;
              }
              return 0;
            },
            target: 0.5
          }
        }
      },
      transfer: {
        trigger: { player: "useCard1" },
        forced: true,
        popup: false,
        charlotte: true,
        filter(event, player) {
          if (event.addCount === false) {
            return false;
          }
          return player.hasHistory("lose", (evt) => {
            if ((evt.relatedEvent || evt.getParent()) !== event) {
              return false;
            }
            for (const i in evt.gaintag_map) {
              if (evt.gaintag_map[i].includes("dcwuyou_transfer")) {
                return true;
              }
            }
            return false;
          });
        },
        async content(event, trigger, player) {
          trigger.addCount = false;
          const stat = player.getStat().card;
          const name = trigger.card.name;
          if (typeof stat[name] === "number") {
            stat[name]--;
          }
        },
        mod: {
          cardname(card, player) {
            const map = player.storage.dcwuyou_transfer;
            if (map && map[card.cardid] && get.itemtype(card) === "card" && card.hasGaintag("dcwuyou_transfer")) {
              return map[card.cardid].name;
            }
          },
          cardnature(card, player) {
            const map = player.storage.dcwuyou_transfer;
            if (map && map[card.cardid] && get.itemtype(card) === "card" && card.hasGaintag("dcwuyou_transfer")) {
              return map[card.cardid].nature || false;
            }
          },
          cardUsable(card) {
            if (!card.cards) {
              return;
            }
            if (card.cards.some((card2) => card2.hasGaintag("dcwuyou_transfer"))) {
              return Infinity;
            }
          },
          targetInRange(card, player) {
            if (!card.cards) {
              return;
            }
            if (card.cards.some((card2) => card2.hasGaintag("dcwuyou_transfer"))) {
              return true;
            }
          }
        }
      },
      targeted: { charlotte: true }
    }
  }

