xianding:dcyixian.code:
{
    audio: 2,
    enable: "phaseUse",
    limited: true,
    skillAnimation: true,
    animationColor: "metal",
    chooseButton: {
      dialog(event, player) {
        const dialog = ui.create.dialog("义贤：你可以选择一项", "hidden");
        dialog.add([
          [
            ["field", "获得场上的所有装备牌"],
            ["discardPile", "获得弃牌堆中的所有装备牌"]
          ],
          "textbutton"
        ]);
        return dialog;
      },
      check(button) {
        const player = get.player();
        if (button.link === "field") {
          return game.filterPlayer().map((current) => {
            const cards2 = current.getCards("e");
            const att = get.sgnAttitude(player, current);
            return cards2.map((card) => {
              return Math.max(player.hasSkill("dcjuewu") ? 5 : 0, get.value(card, player)) - get.value(card, current) * att;
            }).reduce((p, c) => p + c, 0);
          }).reduce((p, c) => p + c, 0);
        }
        if (button.link === "discardPile") {
          return Array.from(ui.discardPile.childNodes).filter((card) => {
            return get.type(card) === "equip";
          }).map((card) => {
            return Math.max(player.hasSkill("dcjuewu") ? 5 : 0, get.value(card, player));
          }).reduce((p, c) => p + c, 0);
        }
        return 0.1;
      },
      backup(links) {
        return {
          audio: "dcyixian",
          filterCard: () => false,
          selectCard: -1,
          pos: links[0],
          filterTarget: () => false,
          selectTarget: -1,
          skillAnimation: true,
          animationColor: "metal",
          async content(event, trigger, player) {
            player.awakenSkill("dcyixian");
            const position = lib.skill.dcyixian_backup.pos;
            const cards2 = [];
            if (position === "field") {
              cards2.addArray(
                game.filterPlayer().map((current) => current.getCards("e")).flat()
              );
            } else {
              cards2.addArray(
                Array.from(ui.discardPile.childNodes).filter((card) => {
                  return get.type(card) === "equip";
                })
              );
            }
            if (!cards2.length) {
              return;
            }
            await player.gain(cards2, position === "field" ? "give" : "gain2");
            const pairs = game.filterPlayer().map((current) => {
              let lostNum = 0;
              current.checkHistory("lose", (evt) => {
                if (evt.getParent(2) === event) {
                  lostNum += evt.cards2.length;
                }
              });
              return [current, lostNum];
            });
            for (const pair of pairs) {
              const [target, num] = pair;
              if (!num) {
                continue;
              }
              const { bool } = await player.chooseBool(`是否令${get.translation(target)}摸${get.cnNumber(num)}张牌并回复1点体力？`).set("choice", get.effect(target, { name: "draw" }, player, player) + get.recoverEffect(target, player, player) / 5 > 0).forResult();
              if (bool) {
                player.line(target, "green");
                await target.draw(num);
                await target.recover();
              }
              if (!event.isMine() && !event.isOnline()) {
                await game.delayx();
              }
            }
          }
        };
      },
      prompt(links) {
        return `点击“确定”，从${links[0] === "field" ? "场上" : "弃牌堆中"}获得所有装备牌`;
      }
    },
    subSkill: {
      backup: {}
    },
    ai: {
      order: 10,
      threaten: 2.9,
      result: {
        player(player) {
          const enemies = game.filterPlayer((current) => {
            return (!get.rawAttitude || get.rawAttitude(player, current) < 0) && get.attitude(player, current) >= 0;
          });
          const knownEnemies = game.filterPlayer((current) => {
            return get.attitude(player, current) < 0;
          });
          if (!knownEnemies.length && player.countCards("e") > 1 || player.getHp() > 3 && enemies.length > 0 && knownEnemies.length < 2 && knownEnemies.length < enemies.length && !knownEnemies.some((enemy) => get.attitude(player, enemy) <= -9)) {
            return 0;
          }
          const val1 = game.filterPlayer().map((current) => {
            const cards2 = current.getCards("e");
            const att = get.sgnAttitude(player, current);
            return cards2.map((card) => {
              return Math.max(player.hasSkill("dcjuewu") ? 5 : 0, get.value(card, player)) - get.value(card, current) * att;
            }).reduce((p, c) => p + c, 0);
          }).reduce((p, c) => p + c, 0);
          const val2 = Array.from(ui.discardPile.childNodes).filter((card) => {
            return get.type(card) === "equip";
          }).map((card) => {
            return Math.max(player.hasSkill("dcjuewu") ? 5 : 0, get.value(card, player));
          }).reduce((p, c) => p + c, 0);
          return Math.max(val1, val2) > 20 ? 4 : 0;
        }
      }
    }
  }

