xianding:qiaojian.code:
{
    audio: 2,
    enable: "phaseUse",
    locked: false,
    filter(event, player) {
      return game.hasPlayer((current) => current !== player && !player.getStorage("qiaojian_used").includes(current));
    },
    selectTarget: 1,
    prompt2: "选择一名其他角色，双方同时弃置至少一张牌并触发后续效果",
    filterTarget(card, player, target) {
      if (target === player) {
        return false;
      }
      if (player.getStorage("qiaojian_used").includes(target)) {
        return false;
      }
      return true;
    },
    async content(event, trigger, player) {
      const targets = event.targets;
      player.addTempSkill("qiaojian_used", "phaseChange");
      targets.forEach((target) => player.markAuto("qiaojian_used", target));
      const resultMap = await game.chooseAnyOL([...targets, player], get.info(event.name).chooseToDiscard, [player, targets]).forResult();
      const resultp = resultMap.get(player);
      const discardedCards = resultp?.cards?.length ? [...resultp.cards] : [];
      const lose_list = [];
      for (const current of [player, ...targets]) {
        const result = resultMap.get(current);
        if (result?.cards?.length) {
          lose_list.push([current, result.cards]);
        }
      }
      await game.loseAsync({ lose_list }).setContent("discardMultiple");
      for (const target of targets) {
        const resultt = resultMap.get(target);
        let numt = 0;
        if (resultt?.cards?.length) {
          discardedCards.addArray(resultt.cards);
        }
        resultt?.cards?.forEach((card) => numt += get.number(card));
        let nump = 0;
        resultp?.cards?.forEach((card) => nump += get.number(card));
        if (nump > numt) {
          await player.recover();
          const choices = ["其下个回合首次使用【杀】与锦囊牌可各额外结算一次", "其下个回合不可使用伤害牌"];
          const result = await player.chooseControl({
            controls: choices,
            prompt: `巧谏：选择一项令${get.translation(target)}执行`,
            forced: true,
            att: get.attitude(player, target),
            ai() {
              return get.event().att > 0 ? "其下个回合首次使用【杀】与锦囊牌可各额外结算一次" : "其下个回合不可使用伤害牌";
            }
          }).forResult();
          let skillNext;
          if (result.index === 0) {
            skillNext = "qiaojian_extra";
          }
          if (result.index === 1) {
            skillNext = "qiaojian_nouse";
          }
          target.addSkill("qiaojian_mark");
          target.markAuto("qiaojian_mark", skillNext);
          target.when("phaseBegin").assign({ firstDo: true }).vars({ skillNext }).then(async (event2, trigger2, player2) => {
            player2.addTempSkill(skillNext);
            player2.unmarkSkill("qiaojian_mark");
            player2.removeSkill("qiaojian_mark");
          });
        } else {
          if (!discardedCards.length) {
            return;
          }
          game.log(player, "获得了", discardedCards);
          await player.gain(discardedCards, "gain2");
          player.addGaintag(discardedCards, "qiaojian_tag");
        }
      }
    },
    mod: {
      ignoredHandcard(card, player) {
        if (card.hasGaintag("qiaojian_tag")) {
          return true;
        }
      },
      cardDiscardable(card, player, name) {
        if (name === "phaseDiscard" && card.hasGaintag("qiaojian_tag")) {
          return false;
        }
      }
    },
    chooseToDiscard(player, source, targetList, eventId) {
      const next = player.chooseToDiscard({
        position: "he",
        selectCard: [1, Infinity],
        prompt: "巧谏：弃置至少一张牌，根据弃牌点数和触发后续效果",
        chooseonly: true,
        forced: true,
        ai(card) {
          const player2 = get.player();
          const sourcex = get.event().sourcex;
          const target = get.event().targets[0];
          const att = get.attitude(sourcex, target);
          if (player2 === sourcex) {
            if (att < 0) {
              if (player2.countCards("h") < 4) ;
              if (ui.selected.cards.length < Math.min(2, target.countCards("h") - 1)) {
                return 6 - get.value(card);
              }
            } else {
              if (ui.selected.cards.length) {
                return 0;
              }
              return 6 - get.value(card);
            }
          } else {
            if (att < 0) {
              if (ui.selected.cards.length <= Math.floor(Math.random() * 4)) {
                return 6 - get.value(card);
              }
            } else {
              return 6 - get.value(card);
            }
          }
          return 0;
        }
      });
      next.set("sourcex", source);
      next.set("id", eventId);
      next.set("targets", targetList);
      next.set("_global_waiting", true);
      return next;
    },
    ai: {
      order: 7,
      result: {
        player(player, target) {
          if (player.countCards("h") > 2) {
            if (get.attitude(player, target) < 0) {
              return 65.7 + Math.random();
            } else {
              return 66;
            }
          }
        }
      }
    },
    subSkill: {
      extra: {
        charlotte: true,
        mark: true,
        marktext: "多",
        intro: {
          markcount: () => 0,
          content: "本回合首次使用【杀】与锦囊牌可各额外结算一次"
        },
        trigger: { player: "useCard" },
        filter(event, player) {
          const card = event.card;
          if (get.type(card) !== "trick" && card.name !== "sha") {
            return false;
          }
          if (card.name === "sha") {
            return player.getHistory("useCard", (evt) => evt.card.name === "sha", event).indexOf(event) === 0;
          }
          return player.getHistory("useCard", (evt) => get.type(evt.card) === "trick", event).indexOf(event) === 0;
        },
        prompt2(event, player) {
          return `令${get.translation(event.card)}额外结算一次`;
        },
        check(event, player) {
          if (get.tag(event.card, "norepeat")) {
            return false;
          }
          return !event.targets || event.targets.reduce((sum, target) => sum + get.effect(target, event.card, player, player), 0) > 0;
        },
        async content(event, trigger, player) {
          game.log(get.translation(trigger.card), "额外结算一次");
          trigger.effectCount++;
        }
      },
      nouse: {
        charlotte: true,
        mark: true,
        marktext: "禁",
        intro: {
          content: "不可使用伤害牌"
        },
        mod: {
          cardEnabled(card, player) {
            if (get.tag(card, "damage")) {
              return false;
            }
          }
        }
      },
      mark: {
        mark: true,
        marktext: "巧",
        charlotte: true,
        intro: {
          name: "巧谏",
          markcount: () => 0,
          content(storage, player) {
            if (player.getStorage("qiaojian_mark").includes("qiaojian_extra")) {
              return "下个回合首次使用【杀】与锦囊牌可各额外结算一次";
            }
            if (player.getStorage("qiaojian_mark").includes("qiaojian_nouse")) {
              return "下个回合不可使用伤害牌";
            }
            return "";
          }
        }
      },
      used: {
        charlotte: true,
        onremove: true,
        mark: true,
        marktext: "谏",
        intro: {
          content: "已对$发动过"
        }
      }
    }
  }

