      return player.getExpansions("dclingxi").length >= num;
    },
    direct: true,
    async content(event, trigger, player) {
      const cards2 = player.getExpansions("dclingxi");
      const num = player.getHistory("useSkill", (evt) => evt.skill === "dczhifou").length + 1;
      const result = await player.chooseButton([`###${get.prompt("dczhifou")}###移去至少${get.cnNumber(num)}张武将牌上的“翼”`, cards2], [num, cards2.length], "allowChooseAll").set("ai", (button) => {
        if (!_status.event.res.bool) {
          return 0;
        }
        if (_status.event.res.cards.includes(button.link)) {
          return 1;
        }
        return 0;
      }).set("num", num).set(
        "res",
        (() => {
          if (player.isPhaseUsing() && player.hasCard((i) => {
            return player.hasValueTarget(i, null, true);
          }, "h")) {
            return false;
          }
          const suits = [];
          let cs = player.getExpansions("dclingxi");
          const cards3 = [];
          let temp = num;
          for (let i = 0; i < cs.length; i++) {
            if (!temp) {
              break;
            }
            const suit = get.suit(cs[i], false);
            if (suits.includes(suit)) {
              cards3.push(cs.splice(i--, 1)[0]);
              temp--;
            } else {
              suits.push(suit);
            }
          }
          while (temp > 0) {
            cards3.push(cs.pop());
            temp--;
          }
          temp = suits.length * 2 - player.countCards("h");
          if (temp > 0 || !temp && num < Math.max(2, 5 - player.hp)) {
            cs = true;
          } else {
            cs = false;
          }
          return {
            bool: cs,
            cards: cards3
          };
        })()
      ).forResult();
      if (result.bool) {
        player.logSkill("dczhifou");
        player.loseToDiscardpile(result.links);
        let list = [];
        const choiceList = ["将一张牌称为“翼”置于你的武将牌上", "弃置两张牌", "失去1点体力"];
