{
    audio: 2,
    trigger: { player: "damageBegin2" },
    filter(event, player) {
      return event.card;
    },
    forced: true,
    async content(event, trigger, player) {
      const num = get.number(trigger.card);
      if (typeof num === "number" && num > 0) {
        trigger.num = num;
      } else {
        trigger.cancel();
      }
    },
    ai: {
      filterDamage: true,
      nodamage: true,
      nofire: true,
      nothunder: true,
      skillTagFilter(player, tag, arg) {
        if (!arg?.card) {
          return false;
        }
        if (tag === "filterDamage") {
          return true;
        }
        return typeof get.number(arg.card) !== "number";
      },
      effect: {
        target(card, player, target, current) {
          let cardx = card;
          if (card.name === "damage" || card.name?.endsWith("Damage")) {
            cardx = (function() {
              let count = 0;
              do {
                const evt = get.event().getParent(count, null, true);
                let name = evt?.skill || evt?.name;
                if (!name) {
                  break;
                }
                if (name.startsWith("pre_")) {
                  name = name.slice(4);
                }
                for (const suffix of ["_backup", "ContentBefore", "ContentAfter", "_cost"]) {
                  if (name.endsWith(suffix)) {
                    name = name.slice(0, name.lastIndexOf(suffix));
                  }
                }
                if (!(name in lib.card) || !evt.card) {
                  continue;
                }
                return evt.card;
              } while (++count < 5);
              return null;
            })();
          }
          if (!cardx) {
            return;
          } else if (get.is.damageCard(cardx) && typeof get.number(cardx) !== "number") {
            return "zeroplayertarget";
          }
        }
      }
    }
  }

