          const getUseValue = (target) => {
            if (get.attitude(player2, target) <= 0) {
              return -1;
            }
            const toUse = [];
            const hp = target.hp;
            let eff = 0;
            let count = Math.max(1, target.countCards("e"));
            while (count--) {
              target.hp = Math.min(target.maxHp, target.hp + toUse.filter((card) => card.name === "tao").length);
              const listx = list.map((info2) => {
                const card = new lib.element.VCard({
                  name: info2[2],
                  nature: info2[3],
                  isCard: true
                });
                return [card, target.getUseValue(card)];
              }).sort((a, b) => {
                return b[1] - a[1];
              });
              const mostValuablePair = listx[0].slice();
              if (mostValuablePair[1] <= 0) {
                mostValuablePair[1] = 0;
              }
              eff += mostValuablePair[1];
              toUse.push(mostValuablePair[0]);
              target.hp = hp;
            }
            if (toUse.length > 1 && eff > 0) {
              eff -= target.getCards("e", (card) => {
                return lib.filter.cardDiscardable(card, target, "dcnuanhui");
              }).map((card) => {
                return get.value(card, target);
              }).reduce((p, c) => {
                return p + c;
              }, 0);
            }
            return eff;
          };
          const playerList = game.filterPlayer().map((current) => [current, getUseValue(current)]).sort((a, b) => b[1] - a[1]);
          if (playerList[0][1] <= 0) {
            return null;
          }
          return playerList[0][0];
        })()
      ).forResult();
    },
    async content(event, trigger, player) {
      const target = event.targets[0];
      if (!target.isUnderControl(true) && !target.isOnline()) {
        game.delayx();
      }
      const total = Math.max(1, target.countCards("e"));
      let count = 0;
      const used = [];
      let discard = false;
      while (count < total) {
        const basicList = get.inpileVCardList((info2) => {
          return info2[0] === "basic" && target.hasUseTarget({ name: info2[2], nature: info2[3], isCard: true });
        });
        if (!basicList.length) {
          game.log("但是", target, "无牌可出！");
          break;
        }
        const result = await target.chooseButton(["暖惠：是否视为使用一张基本牌？", [basicList, "vcard"]]).set("ai", (button) => {
          return get.player().getUseValue({
            name: button.link[2],
            nature: button.link[3],
            isCard: true
          });
        }).forResult();
        if (!result?.bool) {
          game.log("但是", target, "不愿出牌！");
          break;
        }
        const card = new lib.element.VCard({
          name: result.links[0][2],
          nature: result.links[0][3],
          isCard: true
        });
        const result2 = await target.chooseUseTarget(card, true, false).forResult();
        if (!discard && result2?.bool) {
          if (used.includes(result.links[0][2])) {
            discard = true;
          } else {
            used.add(result.links[0][2]);
          }
        }
        count++;
      }
      if (discard) {
        await target.modedDiscard(target.getCards("e"));
      }
    },
    ai: {
      expose: 0.3,
      threaten: 3.7
    }
  }

