                eff = 0;
              } else {
                eff /= 10;
              }
            } else if (target.getHp(true) >= 2) {
              eff += 30;
            }
          }
          return eff;
        }
        if (!target.isDamaged()) {
          eff *= -2;
        }
        if (target.getHp(true) >= 2) {
          return -eff;
        }
        return 0;
      }).set("toDamage", result.index === 1).forResult();
