{
    audio: "ol_shichou",
    enable: "phaseUse",
    viewAs: {
      name: "sha"
    },
    position: "hes",
    viewAsFilter(player) {
      return player.countCards("hes", (card) => {
        return lib.skill.twodcspshichou.filterCard(card, player);
      }) > 0;
    },
    filterCard(card, player) {
      const color = player.getStorage("twodcspshichou_used", [[], []])[0];
      return !color.includes(get.color(card));
    },
    filterTarget(card, player, target) {
      const targetsx = player.getStorage("twodcspshichou_used", [[], []])[1];
      if (targetsx.length > 0 && !targetsx.includes(target)) {
        return false;
      }
      return lib.filter.filterTarget(card, player, target);
    },
    async precontent(event, trigger, player) {
      const { result } = event;
      event.getParent().addCount = false;
      player.addTempSkill("twodcspshichou_used");
      const storage = player.getStorage("twodcspshichou_used");
      storage[0].add(get.color(result.card));
    },
    ai: {
      order(item, player) {
        return get.order({ name: "sha" }, player) + 0.1;
      }
    },
    subSkill: {
      used: {
        init(player, skill) {
          player.storage[skill] = [[], []];
        },
        onremove: true,
        group: "twodcspshichou_directHit"
      },
      directHit: {
        charlotte: true,
        trigger: { player: "useCardToBegin" },
        filter(event, trigger, player) {
          if (!event.target?.isIn()) {
            return false;
          }
          return event.card.name === "sha" && event.skill === "twodcspshichou";
        },
        forced: true,
        popup: false,
        async content(event, trigger, player) {
          const { card, target } = trigger;
          const storage = player.getStorage("twodcspshichou_used");
          storage[1].add(trigger.target);
          let func;
          let prompt;
          if (get.color(card) === "red") {
            prompt = "弃置一张装备牌，否则无法响应此【杀】";
            func = function(card2) {
              return get.type(card2) === "equip";
            };
          } else if (get.color(card) === "black") {
            prompt = "弃置一张黑色手牌，否则无法响应此【杀】";
            func = function(card2) {
              return get.color(card2) === "black" && get.position(card2) === "h";
            };
          } else {
            return;
          }
          const { bool } = await target.chooseToDiscard("he", func, prompt).set("ai", (card2) => {
            const player2 = get.player();
            const trigger2 = get.event().getTrigger();
            if (get.effect(player2, trigger2.card, trigger2.player, player2) >= 0) {
              return 0;
            }
            const num = player2.countCards("hs", { name: "shan" });
            if (num === 0) {
              return 0;
            }
            if (card2.name === "shan" && num <= 1) {
              return 0;
            }
            return 8 - get.value(card2);
          }).forResult();
          if (!bool) {
            trigger.set("directHit", true);
            game.log(target, "不可响应", card);
          }
        }
      }
    }
  }

sp:xinfenyue.code:
{
    enable: "phaseUse",
    usable(skill, player2) {
      return game.players.length - player2.getFriends(true).length;
    },
    audio: "fenyue",
    filter(event2, player2) {
      if (!player2.countCards("h")) {
        return false;
      }
      return game.hasPlayer((target2) => lib.skill.fenyue.filterTarget(null, player2, target2));
    },
    filterTarget(event2, player2, target2) {
      return player2.canCompare(target2);
    },
    async content(event2, trigger2, player2) {
      const { target: target2 } = event2;
      const result = await player2.chooseToCompare(target2).forResult();
      if (!result.bool) {
        event2.finish();
      }
      event2.num = result.num1;
      if (event2.finished) {
        return;
      }
      if (event2.num <= 5 && target2.countGainableCards(player2, "he") > 0) {
        await player2.gainPlayerCard(target2, "he", true);
      }
      if (event2.num <= 9) {
        const card2 = get.cardPile2(function(x) {
          return x.name == "sha";
        });
        if (card2) {
          await player2.gain(card2, "gain2");
        }
      }
      if (event2.num <= 13) {
        const card2 = { name: "sha", nature: "thunder" };
        if (player2.canUse(card2, target2, false)) {
          await player2.useCard(card2, target2, false);
        }
      }
    },
    ai: {
      order: 4,
      result: {
        target(player2, target2) {
          var sort = function(a, b) {
            return b.number - a.number;
          };
          var ps = player2.getCards("h").sort(sort);
          var ts = target2.getCards("h").sort(sort);
          if (ps[0].number > ts[0].number) {
            var effect = get.effect(target2, { name: "sha", nature: "thunder" }, player2, player2);
            if (ps[0].number < 6 && target2.countCards("he") > 1) {
              effect -= 2;
            }
            if (ps[0].number < 10) {
              effect -= 1;
            }
            return effect;
          }
          return ps.length >= ts.length ? -0.5 : 0;
        }
      }
    }
  }

