      const next = player.chooseTarget({
        prompt: get.prompt(event.skill),
        prompt2: "对一名不为你的目标角色造成1点伤害",
        filterTarget: (card, player2, target) => _status.event.targets.includes(target),
        ai: (target) => {
          const player2 = _status.event.player;
          return get.damageEffect(target, player2, player2);
        }
      });
      next.set("targets", targets);
      event.result = await next.forResult();
    },
    async content(event, trigger, player) {
      const target = event.targets[0];
      await target.damage();
    },
    mod: {
      aiOrder(player, card, num) {
        if (_status.currentPhase !== player) {
          return;
        }
        const cardsh = [];
        if (Array.isArray(card.cards)) {
          cardsh.addArray(card.cards.filter((card2) => get.position(card2) === "h"));
        }
        const del = player.countCards("h") - cardsh.length - player.getHistory("useCard").length - 1;
        if (del < 0) {
          return;
        }
        if (del > 0) {
          if (card.name === "sha" || get.type(card, null, player) !== "trick") {
            return num / 3;
          }
          return num + 1;
        }
        return num + 15;
      }
    }
