    },
    async cost(event, trigger, player) {
      const choices = ["选项一"];
      const choiceList = [`令${get.translation(trigger.card)}不计入次数`, "获得此牌"];
      if (trigger.cards.length) {
        choices.push("选项二");
        choiceList[1] = `获得${get.translation(trigger.cards)}`;
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      choices.push("cancel2");
      let choice = 0;
      if (choices.length === 3 && trigger.addCount === false) {
        choice = 1;
      } else if (player.getCardUsable({ name: "sha" }) >= player.countCards("hs", "sha") && choices.length === 3) {
        choice = 1;
      }
      const result = await player.chooseControl({
        controls: choices,
        choiceList,
        ai: () => choice
      }).forResult();
      event.result = {
        bool: result.control !== "cancel2",
        cost_data: result.control
      };
    },
    async content(event, trigger, player) {
      const choice = event.cost_data;
      game.log(player, "选择了", `#y${choice}`);
      if (choice === "选项一") {
        if (trigger.addCount !== false) {
          trigger.addCount = false;
          const stat = player.getStat().card;
          const name = trigger.card.name;
          if (typeof stat[name] === "number") {
            stat[name]--;
          }
        }
      } else {
        const cards2 = trigger.cards.filterInD();
        if (cards2.length) {
          await player.gain({ cards: cards2, animate: "gain2" });
        }
      }
    }
  }

