{
    audio: "gushe",
    enable: "phaseUse",
    filterTarget(card2, player2, target2) {
      return player2.canCompare(target2);
    },
    selectTarget: [1, 3],
    filter(event2, player2) {
      return player2.countMark("regushe") + player2.countMark("regushe2") < 7 && player2.countCards("h") > 0;
    },
    multitarget: true,
    multiline: true,
    async content(event2, trigger2, player2) {
      player2.addTempSkill("regushe2");
      const { targets: targets2 } = event2;
      const next = player2.chooseToCompare(targets2);
      next.callback = lib.skill.regushe.callback;
      await next;
    },
    intro: {
      name: "饶舌",
      content: "mark"
    },
    async callback(event2, trigger2, player2) {
      const { target: target2 } = event2;
      if (event2.winner !== player2) {
        target2.chat(lib.skill.gushe.chat[player2.countMark("regushe")]);
        await game.delay();
        player2.addMark("regushe", 1);
        if (player2.countMark("regushe") >= 7) {
          await player2.die();
        }
      } else {
        player2.addMark("regushe2", 1, false);
      }
      if (event2.winner !== player2) {
        const result = await player2.chooseToDiscard("he", "弃置一张牌，或摸一张牌").set("ai", function() {
          return -1;
        }).forResult();
        if (!result.bool) {
          await player2.draw();
        }
      }
      if (event2.winner !== target2) {
        const result2 = await target2.chooseToDiscard("he", "弃置一张牌，或令" + get.translation(player2) + "摸一张牌").set("ai", function(card2) {
          if (_status.event.goon) {
            return 6 - get.value(card2);
          }
          return 0;
        }).set("goon", get.attitude(target2, player2) < 0).forResult();
        if (!result2.bool) {
          await player2.draw();
        }
      }
    },
    ai: {
      order: 7,
      result: {
        target(player2, target2) {
          var num = ui.selected.targets.length + 1;
          if (num + player2.countMark("regushe") <= 6) {
            return -1;
          }
          var hs = player2.getCards("h");
          for (var i = 0; i < hs.length; i++) {
            if (get.value(hs[i]) <= 6) {
              switch (hs[i].number) {
                case 13:
                  return -1;
                case 12:
                  if (player2.countMark("regushe") + num <= 8) {
                    return -1;
                  }
                  break;
                case 11:
                  if (player2.countMark("regushe") + num <= 7) {
                    return -1;
                  }
                  break;
                default:
                  if (hs[i].number > 5 && player2.countMark("regushe") + num <= 6) {
                    return -1;
                  }
              }
            }
          }
          return 0;
        }
      }
    },
    marktext: "饶"
  }

