xianding:dclingyin.code:
{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    filter(event, player) {
      return player.getExpansions("dcwangyuan").length;
    },
    async cost(event, trigger, player) {
      const cards2 = player.getExpansions("dcwangyuan");
      const redCards = cards2.filter((card) => get.color(card) === "red");
      let color = 1;
      if (redCards.length !== cards2.length && redCards.length !== 0 && cards2.length > game.roundNumber) {
        if (redCards.length <= game.roundNumber) {
          color = "red";
        } else if (cards2.length - redCards.length <= game.roundNumber) {
          color = "black";
        }
      }
      const result = await player.chooseButton({
        createDialog: [`${get.prompt(event.skill)}（当前轮数：${get.cnNumber(game.roundNumber, true)}）`, cards2],
        selectButton: [1, game.roundNumber],
        ai: (button) => {
          if (ui.selected.buttons.length > 0 && ui.selected.buttons.length === player.getExpansions("dcwangyuan").length - 1) {
            return 0;
          }
          if (color === 1) {
            return get.value(button.link);
          }
          if (color) {
            return get.color(button.link) === color ? 1 : 0;
          }
          return 0;
        }
      }).forResult();
      event.result = {
        bool: result.bool,
        cost_data: result.links
      };
    },
    async content(event, trigger, player) {
      const gainedCards = event.cost_data;
      await player.gain({ cards: gainedCards, animate: "gain2" });
      const remainingCards = player.getExpansions("dcwangyuan").removeArray(gainedCards);
      if (remainingCards.length <= 1 || get.color(remainingCards) !== "none") {
        player.addTempSkill("dclingyin_effect");
        player.addMark("dclingyin_effect", 1, false);
        game.log(player, "获得了", "#g【铃音】", "的后续效果");
      }
    },
    ai: {
      combo: "dcwangyuan",
      threaten: 3
    },
    subSkill: {
      effect: {
        audio: "dclingyin",
        enable: "phaseUse",
        trigger: { source: "damageBegin1" },
        viewAs: { name: "juedou" },
        charlotte: true,
        forced: true,
        onremove: true,
        prompt: "将一张武器牌或防具牌当【决斗】使用",
