{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    filter(event, player) {
      return player.countCards("h") > 7;
    },
    direct: true,
    locked: true,
    intro: {
      markcount: "expansion",
      content: "expansion"
    },
    async content(event, trigger, player) {
      const num = player.countCards("h") - 7;
      const result = await player.chooseCard({
        prompt: `佛宗：将${get.cnNumber(num)}张手牌置于武将上`,
        forced: true,
        selectCard: num
      }).forResult();
      if (result.bool) {
        player.logSkill("dcfozong");
        await player.addToExpansion({
          cards: result.cards,
          source: player,
          animate: "give",
          gaintag: ["dcfozong"]
        });
      }
      if (player.getExpansions("dcfozong").length < 7) {
        return;
      }
      const targets = game.filterPlayer((target) => target !== player).sortBySeat(player);
      await game.delayx();
      for (const target of targets) {
        player.line(target);
        const cards2 = player.getExpansions("dcfozong");
        let choiceResult = { bool: false };
        if (cards2.length) {
          const refuse = get.attitude(target, player) < 1 && get.effect(player, { name: "losehp" }, player, target) > 0;
          choiceResult = await target.chooseButton({
            createDialog: [`###佛宗###<div class="text center">获得一张牌并令${get.translation(player)}回复1点体力，或点击“取消”令其失去1点体力</div>`, cards2],
            ai: (button) => get.value(button.link) - (refuse ? 7.5 : 0)
          }).forResult();
        }
        if (!choiceResult.bool) {
          await player.loseHp();
          if (player.isDead() || !player.isIn()) {
            break;
          }
          continue;
        }
        const card = choiceResult.links[0];
        await target.gain({
          cards: [card],
          source: player,
          animate: "give"
        });
        await player.recover({ source: target });
      }
