        if (player.countCards("hs", button.link[2]) > 0) {
          return 0;
        }
        if (button.link[2] === "wugu") {
          return;
        }
        const effect = player.getUseValue(button.link[2]);
        if (effect > 0) {
          return effect;
        }
        return 0;
      },
      backup(links, player) {
        return {
          filterCard(card, player2, event) {
            return get.number(card) <= player2.countMark("dclingfang");
          },
