      return target.hasSkill("dctongguan_guojue") && guojue || target.hasSkill("dctongguan_renzhi") && renzhi;
    },
    getSpecialProperties(target) {
      let guojue = false;
      let renzhi = false;
      for (const current of game.filterPlayer2()) {
        if (current === target) {
          continue;
        }
        if (!guojue && current.hasHistory("lose", (evt) => {
          if (evt.type === "discard") {
            return (evt.discarder || evt.getParent(2).player) === target && Boolean(evt.getl(current).cards2.length);
          }
          if (evt.type !== "gain") {
            return false;
          }
          const gainEvent = evt.getParent();
          if (gainEvent.giver || gainEvent.getParent().name === "gift") {
            return false;
          }
          const cards2 = gainEvent.getg(target);
          return cards2.length > 0 && gainEvent.getl(current).cards2.some((card) => cards2.includes(card));
        })) {
          guojue = true;
        }
        if (!renzhi && current.hasHistory("gain", (evt) => {
          if (evt.giver !== target || evt.getParent().name === "gift") {
            return false;
          }
          return Boolean(evt.cards.length);
        })) {
          renzhi = true;
        }
      }
      return { guojue, renzhi };
    },
    rules: [(target) => target.getHistory("sourceDamage").length, (target) => target.countCards("h") > target.hp || game.getGlobalHistory("changeHp", (evt) => evt.player === target && evt.getParent().name === "recover").length > 0, (target) => target.getHistory("gain", (evt) => evt.getParent().name === "draw" && evt.getParent("phaseDraw").name !== "phaseDraw").length, (target, bool) => bool, (target, bool) => bool],
    async content(event, trigger, player) {
      const target = trigger.player;
      const skills2 = lib.skill.dctongguan.derivation;
      const { guojue, renzhi } = lib.skill.dcmengjie.getSpecialProperties(target);
      const specialProperties = [guojue, renzhi];
      for (let index = 0; index < skills2.length; index++) {
        if (!target.hasSkill(skills2[index]) || !lib.skill.dcmengjie.rules[index](target, specialProperties[index - 3])) {
