{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event, player) {
      return player.hp > 0 && ui.discardPile.childNodes.length > 0;
    },
    async cost(event, trigger, player) {
      const cards2 = Array.from(ui.discardPile.childNodes);
      const gains = cards2.slice();
      const history = game.getAllGlobalHistory("cardMove", (evt) => {
        if (evt.name === "lose") {
          return evt.position === ui.discardPile;
        }
        return evt.name === "cardsDiscard";
      });
      for (const evt of history.slice().reverse()) {
        const cards22 = evt.cards.filter((card) => cards2.includes(card));
        if (cards22.length) {
          if (lib.skill.dcfuxue.isUse(evt)) {
            gains.removeArray(cards22);
          }
          cards2.removeArray(cards22);
        }
        if (!cards2.length) {
          break;
        }
      }
      if (!gains.length) {
        event.result = { bool: false };
        return;
      }
      const num = player.hp;
      const result = await player.chooseButton({
        createDialog: [`复学：选择获得至多${get.cnNumber(num)}张牌`, gains],
        selectButton: [1, num],
        ai: (button) => {
          const card = button.link;
          const getCount = (card2) => player.countCards("h", card2.name) + ui.selected.buttons.filter((button2) => button2.link.name === card2.name).length;
          const value = player.getUseValue(card);
          if (card.name === "tao" && getCount(card) >= player.getDamagedHp()) {
            return 0;
          }
          if (card.name === "sha" && getCount(card) >= player.getCardUsable("sha")) {
            return 0;
          }
          return value;
        }
      }).forResult();
      event.result = {
        bool: result.bool,
        cost_data: result.links
      };
    },
    async content(event, trigger, player) {
      await player.gain({
        cards: event.cost_data,
        animate: "gain2",
        gaintag: ["dcfuxue"]
      });
    },
    isUse(event) {
      if (event.name !== "cardsDiscard") {
        return false;
      }
      const evtx = event.getParent();
      if (evtx.name !== "orderingDiscard") {
        return false;
      }
      const relatedEvent = evtx.relatedEvent || evtx.getParent();
      return relatedEvent.name === "phaseJudge" || relatedEvent.name === "useCard";
    },
    group: "dcfuxue_draw",
    subSkill: {
      draw: {
        audio: "dcfuxue",
        trigger: { player: "phaseJieshuBegin" },
        forced: true,
        locked: false,
        mod: {
          aiOrder(player, card, num) {
            if (get.itemtype(card) === "card" && card.hasGaintag("dcfuxue")) {
              return num + 0.5;
            }
          }
        },
        filter(event, player) {
          return player.hp > 0 && !player.hasCard((card) => card.hasGaintag("dcfuxue"), "h");
        },
        async content(event, trigger, player) {
          await player.draw(player.hp);
        }
      }
    }
  }

