      for (const current of players) {
        list.remove(current.name);
        list.remove(current.name1);
        list.remove(current.name2);
      }
      list = list.randomGets(4);
      const skills2 = [];
      for (const name of list) {
        skills2.addArray(
          (lib.character[name][3] || []).filter((skill) => {
            const info2 = get.info(skill);
            return info2 && !info2.charlotte;
          })
        );
      }
      if (!list.length || !skills2.length) {
        event.result = {
          bool: false,
          skills: []
        };
        await player.draw(3);
        return;
      }
      if (player.isUnderControl()) {
        game.swapPlayerAuto(player);
      }
      const switchToAuto = () => {
        _status.imchoosing = false;
        event._result = {
          bool: true,
          skills: skills2.randomGets(2)
        };
        if (event.dialog) {
          event.dialog.close();
        }
        if (event.control) {
          event.control.close();
        }
      };
      const chooseButton = (list2, skills3) => {
        const currentEvent = _status.event;
        if (!currentEvent._result) {
          currentEvent._result = {};
        }
        currentEvent._result.skills = [];
        const selectedSkills = currentEvent._result.skills;
        const dialog = ui.create.dialog("请选择获得至多两个技能", [list2, "character"], "hidden");
        currentEvent.dialog = dialog;
        const table = document.createElement("div");
        table.classList.add("add-setting");
        table.style.margin = "0";
        table.style.width = "100%";
        table.style.position = "relative";
        for (const skill of skills3) {
