          td.addEventListener(lib.config.touchscreen ? "touchend" : "click", (clickEvent) => {
            if (_status.dragged) {
              return;
            }
            if (_status.justdragged) {
              return;
            }
            _status.tempNoButton = true;
            setTimeout(() => {
              _status.tempNoButton = false;
