        return false;
      }
      const card = player.getEquip("dagongche");
      if (!card) {
        return false;
      }
      let num = 0;
      for (let i = 1; i <= 3; i++) {
        const key = `大攻车选项${get.cnNumber(i, true)}`;
        if (card.storage[key]) {
          num += card.storage[key];
        }
      }
      return num < 5;
    },
    async cost(event, trigger, player) {
      const choiceList = ["令【杀】无距离限制且无视防具", "令【杀】的可选目标数+1", "令后续的弃牌数量+1"];
      const list = [];
      const card = player.getEquip("dagongche");
      for (let i = 1; i <= 3; i++) {
        const key = `大攻车选项${get.cnNumber(i, true)}`;
        const num = card.storage[key];
        if (i === 1) {
          if (!num) {
            list.push("选项一");
          } else {
            choiceList[0] = `<span style="opacity:0.5; ">${choiceList[0]}（已强化）</span>`;
          }
        } else {
          list.push(`选项${get.cnNumber(i, true)}`);
          if (num) {
            choiceList[i - 1] += `（已强化${num}次）`;
          }
        }
      }
      const result = await player.chooseControl({
        controls: [...list, "cancel2"],
        prompt: "是否发动【陷筑】强化【大攻车】？",
        choiceList,
        ai: () => {
          const player2 = _status.event.player;
          const controls = _status.event.controls.slice(0);
          const getval = (choice) => {
            const card2 = player2.getEquip("dagongche");
            if (choice === "选项一") {
              card2.storage.大攻车选项一 = 1;
              const goon = game.hasPlayer((current2) => {
                let eff1 = 0;
                let eff2 = 0;
                const cardx = { name: "sha", isCard: true };
                if (player2.canUse(cardx, current2)) {
                  eff1 = get.effect(current2, cardx, player2, player2);
                }
                cardx.storage = { dagongche: true };
                if (player2.canUse(cardx, current2)) {
                  eff2 = get.effect(current2, cardx, player2, player2);
                }
                return eff2 > eff1;
              });
              delete card2.storage.大攻车选项一;
              if (goon) {
                return 5;
              }
              return 0;
            } else if (choice === "选项二") {
              let num = 1;
              if (card2.storage.大攻车选项二) {
                num += card2.storage.大攻车选项二;
              }
              const cardx = { name: "sha", isCard: true };
              if (game.countPlayer((current2) => player2.canUse(cardx, current2) && get.effect(current2, cardx, player2, player2) > 0) > num) {
                return 2;
              }
            } else if (choice === "选项三") {
              return 1;
            }
            return 0;
          };
          let eff = 0;
          let current = "cancel2";
          for (const control of controls) {
            const effx = getval(control);
            if (effx > eff) {
              eff = effx;
              current = control;
            }
          }
          return current;
        }
      }).forResult();
      event.result = {
        bool: result.control !== "cancel2",
        cost_data: result.control
      };
    },
    async content(event, trigger, player) {
      const equip = player.getEquip("dagongche");
      const key = `大攻车${event.cost_data}`;
      if (!equip.storage[key]) {
        equip.storage[key] = 0;
      }
      equip.storage[key]++;
      lib.skill.dcwanglu.broadcast(player);
    },
    ai: {
      combo: "dcwanglu"
    }
  }

