xianding:dckaiji.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event, player) {
      if (player.maxHp <= 0) {
        return false;
      }
      if (!player.storage.dckaiji) {
        return true;
      }
      return player.hasCard((card) => lib.filter.cardDiscardable(card, player, "phaseUse"), "he");
    },
    filterCard(card, player) {
      if (!player.storage.dckaiji) {
        return false;
      }
      return true;
    },
    position: "he",
    selectCard() {
      const player = _status.event.player;
      return player.storage.dckaiji ? [1, player.maxHp] : -1;
    },
    check(card) {
      const player = _status.event.player;
      if (!player.hasSkill("dcpingxi")) {
        if (ui.selected.cards.length) {
          return 0;
        }
        if (player.needsToDiscard()) {
          return 12 - get.value(card);
        }
        return 2 * player.hp + 1.5 - get.value(card);
      }
      const num = lib.skill.dcpingxi.getNum() + ui.selected.cards.length;
      if (num < game.countPlayer((current) => {
        if (current === player || current.countCards("he") === 0) {
          return false;
        }
        return get.effect(current, { name: "guohe_copy2" }, player, player) + get.effect(current, { name: "sha" }, player, player) > 0;
      })) {
        if (get.position(card) === "h" && player.needsToDiscard(0, (i, player2) => {
          return !ui.selected.cards.includes(i) && !player2.canIgnoreHandcard(i);
        })) {
          return 7 + 1 / Math.max(1, get.value(card));
        }
        return 7 - get.value(card);
      }
      return 0;
    },
    allowChooseAll: true,
    async content(event, trigger, player) {
      player.changeZhuanhuanji("dckaiji");
      const cards2 = event.cards;
      if (!cards2.length) {
        player.draw(Math.min(player.maxHp, 5));
      }
    },
    zhuanhuanji: true,
    mark: true,
    marktext: "☯",
    intro: {
      content: (storage) => `转换技。出牌阶段限一次，你可以${storage ? "弃置至多X张牌" : "摸X张牌"}（X为你的体力上限且至多为5）。`
    },
    ai: {
      threaten: 1.6,
      order(item, player) {
        if (player.storage.dckaiji) {
          return 0.1;
        }
        return 8;
      },
      result: { player: 1 }
    }
  }

