      ["受到X点伤害", "弃置X张牌", "翻面并横置", "随机执行一个已经移除过的选项"]
    ],
    filterx: [
      [
        () => true,
        () => true,
        /*player => player.isTurnedOver() || player.isLinked()*/
        () => true,
        () => true
      ],
      [
        () => true,
        /*player =>
        	player.hasCard(function (card) {
        		return lib.filter.cardDiscardable(card, player, "caiyi");
        	}, "he"),*/
        () => true,
        /*player => !player.isTurnedOver() || !player.isLinked(),*/
        () => true,
        () => true
      ]
    ],
    async cost(event, trigger, player) {
      player.storage.caiyi_info ??= [[], []];
      const index = player.storage.caiyi ? 1 : 0;
      const list = player.storage.caiyi_info[index];
      const choices = lib.skill[event.skill].choices[index];
      const numbers = ["⒈", "；⒉", "；⒊", "；⒋"];
      let num = 4 - list.length;
      let str = "令一名角色选择执行其中一项：";
      for (let i = 0; i < 4; i++) {
        if (list.includes(i)) {
          continue;
        }
        if (i === 3 && !list.length) {
          continue;
        }
        str += numbers.shift();
        str += choices[i];
      }
      str += "。";
      num++;
      str = str.replace(/X/g, (match, index2) => {
        return get.cnNumber(num++);
      });
      event.result = await player.chooseTarget({
        prompt: `${get.prompt("caiyi")}（当前状态：${!index ? "阳" : "阴"}）`,
        prompt2: str,
        ai(target) {
          const player2 = _status.event.player;
          return (player2.storage.caiyi ? -1 : 1) * get.attitude(player2, target);
        }
      }).forResult();
    },
    async content(event, trigger, player) {
      player.storage.caiyi_info ??= [[], []];
      const index = event.index = player.storage.caiyi ? 1 : 0;
      const list = player.storage.caiyi_info[index];
      const num = event.num = 4 - list.length;
      const {
        targets: [target]
      } = event;
      event.target = target;
      player.changeZhuanhuanji(event.name);
      if (index === 0) {
        const list2 = [];
        const getStr = (num2) => get.cnNumber(num2);
        const choiceList = [`回复${getStr(num + 1)}点体力。`, `摸${getStr(num + 2)}张牌。`, "将武将牌翻至正面且重置。", "随机执行一个已经被移除的选项。"];
        const storage = player.storage.caiyi_info[event.index];
        for (let i = 0; i < 4; i++) {
          if (storage.includes(i)) {
            choiceList[i] = `<span style="text-decoration:line-through; opacity:0.5; ">${choiceList[i]}</span>`;
          } else if (!lib.skill.caiyi.filterx[event.index][i](target) || i === 3 && !storage.length) {
            choiceList[i] = `<span style="opacity:0.5;">${choiceList[i]}</span>`;
          } else {
            list2.push(`选项${get.cnNumber(i + 1, true)}`);
          }
        }
        if (!list2.length) {
          return;
        }
        const result = await target.chooseControl({
          controls: list2,
          choiceList,
          ai() {
            const evt = _status.event;
            const player2 = evt.player;
            const list3 = evt.controls.slice(0);
            const gett = function(choice) {
              if (choice === "cancel2") {
                return 0.1;
              }
              let max = 0;
              const func = {
                选项一(current) {
                  max = get.recoverEffect(current, player2, player2) * Math.min(evt.getParent().num + 1, player2.getDamagedHp());
                },
                选项二(target2) {
