          const list3 = player.storage.caiyi_info[event.index].filter((i) => {
            return i !== 3 && lib.skill.caiyi.filterx[event.index][i](target);
          });
          if (!list3.length) {
            return;
          }
          index2 = list3.randomGet();
        }
        switch (index2) {
          case 0:
            await target.recover({ num: num + 1 });
            break;
          case 1:
            await target.draw({ num: num + 2 });
            break;
          case 2:
            await target.turnOver(false);
            await target.link(false);
            break;
        }
      } else if (index === 1) {
        const list2 = [];
        const getStr = (num2) => get.cnNumber(num2);
        const choiceList = [`受到${getStr(num + 1)}点伤害。`, `弃置${getStr(num + 2)}张牌。`, "将武将牌翻至背面并横置。", "随机执行一个已经被移除的选项。"];
        const storage = player.storage.caiyi_info[event.index];
        for (let i = 0; i < 4; i++) {
          if (storage.includes(i)) {
            choiceList[i] = `<span style="text-decoration:line-through; opacity:0.5; ">${choiceList[i]}</span>`;
          } else if (!lib.skill.caiyi.filterx[event.index][i](target) || i === 3 && !storage.length) {
            choiceList[i] = `<span style="opacity:0.5;">${choiceList[i]}</span>`;
          } else {
            list2.push(`选项${get.cnNumber(i + 1, true)}`);
          }
        }
        if (!list2.length) {
          return;
        }
        const result = await target.chooseControl({
          controls: list2,
          choiceList,
          ai() {
            const evt = _status.event;
            const player2 = evt.player;
            const list3 = evt.controls.slice(0);
            const gett = function(choice) {
              if (choice === "cancel2") {
                return 0.1;
              }
              let max = 0;
              const func = {
                选项一(current) {
                  max = get.effect(current, { name: "damage" }, player2, player2) * (evt.getParent().num + 1);
                },
                选项二(target2) {
                  max = get.effect(target2, { name: "guohe_copy2" }, player2, player2) * Math.min(player2.countCards("he"), evt.getParent().num + 2);
                },
                选项三(target2) {
                  if (!player2.isTurnedOver()) {
                    max -= 20;
                  }
                  if (!player2.isLinked()) {
                    max += get.effect(player2, { name: "tiesuo" }, player2, player2);
                  }
                },
                选项四(target2) {
                  max = -3;
                }
              }[choice];
              func(player2);
              return max;
            };
            return list3.sort((a, b) => {
              return gett(b) - gett(a);
            })[0];
          }
        }).forResult();
        let index2 = ["选项一", "选项二", "选项三", "选项四"].indexOf(result.control);
        player.storage.caiyi_info[event.index].add(index2);
        if (index2 === 3) {
