xianding:dclianyou.code:
{
    audio: 2,
    trigger: { player: ["damageEnd", "phaseBegin"] },
    filter(event, player) {
      return !(player.getStorage("dclianyou").includes("recover") && player.getStorage("dclianyou").includes("equip") && player.getStorage("dclianyou").includes("draw"));
    },
    async cost(event, trigger, player) {
      const choiceList = [];
      const name = "dclianyou";
      if (!player.getStorage(name).includes("recover")) {
        if (game.hasPlayer((current) => current.isDamaged())) {
          choiceList.push(["recover", "令一名角色回复1点体力"]);
        }
      }
      if (!player.getStorage(name).includes("equip")) {
        choiceList.push(["equip", "令一名角色随机使用两张装备牌"]);
      }
      if (!player.getStorage(name).includes("draw")) {
        choiceList.push(["draw", "摸三张牌并可以交给一名其他角色三张牌"]);
      }
      if (choiceList.length) {
        const result = await player.chooseButton({
          createDialog: [`${get.prompt("dclianyou")}选择一项`, [choiceList, "textbutton"]],
          selectButton: 1,
          ai(button) {
            if (button.link === "recover") {
              let max = 0;
              for (const current of game.filterPlayer()) {
                const num = current.getDamagedHp() * get.recoverEffect(current, player, player);
                if (num > max) {
                  max = num;
                }
              }
              return max;
            }
            if (button.link === "draw") {
              return 3.95 + 0.1 * Math.random();
            }
            if (button.link === "equip") {
              return 4;
            }
            return 0;
          }
        }).set("choiceList", choiceList).forResult();
        if (result.bool) {
          player.markAuto(name, result.links[0]);
          event.result = { bool: true, cost_data: { choice: result.links[0] } };
        }
      }
    },
    async content(event, trigger, player) {
      const { choice } = event.cost_data;
      if (choice === "recover") {
        const result = await player.chooseTarget({
          prompt: "怜幼：令一名角色回复1点体力",
          filterTarget(card, player2, target) {
            return target.isDamaged();
          },
          forced: true,
          ai(target) {
            return target.getDamagedHp() * get.recoverEffect(target, player, player);
          }
        }).forResult();
        if (result.bool) {
          await result.targets[0].recover();
        }
      } else if (choice === "equip") {
        const result = await player.chooseTarget({
          prompt: "怜幼：选择一名角色，随机使用两张装备牌",
          forced: true,
          ai(target) {
            return get.attitude(get.player(), target);
          }
        }).forResult();
        if (result?.targets?.length) {
          const target = result.targets[0];
          for (let i = 1; i <= 2; i++) {
            const card = get.cardPile((card2) => get.type(card2) === "equip" && target.canUse(card2, target), void 0, "bottom");
            if (!card) {
              break;
            }
            await target.chooseUseTarget({
              card,
              forced: true,
              nopopup: true
            });
          }
        }
      } else if (choice === "draw") {
        await player.draw(3);
        const result = await player.chooseCardTarget({
          filterTarget(card, player2, target) {
            return lib.filter.notMe;
          },
          prompt: "怜幼：是否交给一名其他角色三张牌？",
          selectCard: 3,
          position: "he",
          ai1(card) {
            return 1 / Math.max(0.1, get.value(card));
          },
          ai2(target) {
            const player2 = get.player();
            return get.attitude(player2, target);
          }
        }).forResult();
        if (result?.cards?.length && result.targets?.length) {
          const {
            cards: cards2,
            targets: [target]
          } = result;
          player.line(target);
          await player.give(cards2, target);
        }
      }
    },
    group: ["dclianyou_restore"],
    subSkill: {
      restore: {
        charlotte: true,
        forced: true,
        firstDo: true,
        popup: false,
        trigger: {
          global: "roundStart"
        },
        async content(event, trigger, player) {
          ["recover", "equip", "draw"].forEach((index) => player.unmarkAuto("dclianyou", index));
        }
      }
    }
  }

