      await player.showCards(cards2, `${get.translation(player)}发动了【${get.translation(event.name)}】`, true).set("clearArena", false);
      const next = player.chooseToMove(`潜龙：获得至多${get.cnNumber(Math.min(3, player.getDamagedHp()))}张牌并将其余牌置于牌堆底（右为底）`);
      next.set("list", [["置于牌堆底", cards2], ["自己获得"]]);
      next.set("filterMove", (from, to, moved) => {
        if (moved[0].includes(from.link)) {
          if (typeof to === "number") {
            if (to === 1) {
              if (moved[1].length >= _status.event.player.getDamagedHp()) {
                return false;
              }
            }
            return true;
          }
        }
        return true;
      });
      next.set("processAI", (list) => {
        const cards3 = list[0][1].slice(0);
        const player2 = _status.event.player;
        cards3.sort((a, b) => {
          return get.value(b, player2) - get.value(a, player2);
        });
        if (!player2.storage.juetao && player2.hasSkill("juetao") && player2.hasSha()) {
          let gain;
          let bottom;
          const pai = cards3.filter((card) => card.name !== "sha");
          pai.sort((a, b) => {
            return get.value(b, player2) - get.value(a, player2);
          });
          gain = pai.splice(0, player2.getDamagedHp());
          bottom = cards3.slice(0);
          bottom.removeArray(gain);
          return [bottom, gain];
        }
        return [cards3, cards3.splice(0, player2.getDamagedHp())];
      });
      const result = await next.forResult();
      game.broadcastAll(ui.clear);
      if (result.moved?.length) {
        const { moved } = result;
        if (moved[0].length > 0) {
          game.log(player, "将", moved[0], "置于牌堆底");
          await game.cardsGotoPile(moved[0]);
        }
        if (moved[1].length > 0) {
          await player.gain(moved[1], "gain2");
        }
      }
    },
    ai: {
