xianding:refenyin.code:
{
    audio: 2,
    audioname: ["wufan"],
    trigger: { global: ["loseAfter", "cardsDiscardAfter", "loseAsyncAfter", "equipAfter"] },
    forced: true,
    filter(event, player) {
      if (player !== _status.currentPhase) {
        return false;
      }
      const cards2 = event.getd();
      if (!cards2.length) {
        return false;
      }
      const list = [];
      let num = cards2.length;
      for (let i = 0; i < cards2.length; i++) {
        const card = cards2[i];
        list.add(get.suit(card, false));
      }
      game.getGlobalHistory("cardMove", (evt) => {
        if (evt.name !== "lose" && evt.name !== "cardsDiscard") {
          return false;
        }
        if (evt.name === "lose" && evt.position !== ui.discardPile) {
          return false;
        }
        if (evt === event || evt.getParent() === event) {
          return false;
        }
        num += evt.cards.length;
        for (let i = 0; i < evt.cards.length; i++) {
          const card = evt.cards[i];
          list.remove(get.suit(card, evt.cards2 && evt.cards2.includes(card) ? evt.player : false));
        }
      });
      player.storage.refenyin_mark2 = num;
      return list.length > 0;
    },
    async content(event, trigger, player) {
      const list = [];
      const list2 = [];
      const cards2 = trigger.getd();
      for (let i = 0; i < cards2.length; i++) {
        const card = cards2[i];
        const suit = get.suit(card, false);
        list.add(suit);
        list2.add(suit);
      }
      game.getGlobalHistory("cardMove", (evt) => {
        if (evt.name !== "lose" && evt.name !== "cardsDiscard") {
          return false;
        }
        if (evt.name === "lose" && evt.position !== ui.discardPile) {
          return false;
        }
        if (evt === trigger || evt.getParent() === trigger) {
          return false;
        }
        for (let i = 0; i < evt.cards.length; i++) {
          const card = evt.cards[i];
          const suit = get.suit(card, false);
          list.remove(suit);
          list2.add(suit);
        }
      });
      list2.sort();
      player.draw(list.length);
      player.storage.refenyin_mark = list2;
      player.addTempSkill("refenyin_mark");
      player.markSkill("refenyin_mark");
    },
    subSkill: {
      mark: {
        charlotte: true,
        onremove(player) {
          delete player.storage.refenyin_mark;
          delete player.storage.refenyin_mark2;
        },
        intro: {
          content(s, p) {
            let str = "本回合已经进入过弃牌堆的卡牌的花色：";
            for (let i = 0; i < s.length; i++) {
              str += get.translation(s[i]);
            }
            str += "<br>本回合进入过弃牌堆的牌数：";
            str += p.storage.refenyin_mark2;
            return str;
          }
        }
      }
    }
  }

xianding:liji.code:
{
    enable: "phaseUse",
    usable(skill, player) {
      return get.event().liji_num;
    },
    audio: 2,
    onChooseToUse(event) {
      if (game.online) {
        return;
      }
      let num = 0;
      const evt2 = event.getParent();
      if (!evt2.liji_all) {
        evt2.liji_all = game.players.length > 4 ? 8 : 4;
      }
      game.getGlobalHistory("cardMove", (evt) => {
        if (evt.name === "cardsDiscard" || evt.name === "lose" && evt.position === ui.discardPile) {
          num += evt.cards.length;
        }
      });
      event.set("liji_num", Math.floor(num / evt2.liji_all));
    },
    filterCard: true,
    position: "he",
    check(card) {
      const val = get.value(card);
      if (!_status.event.player.getStorage("refenyin_mark").includes(get.suit(card))) {
        return 12 - val;
      }
      return 8 - val;
    },
    filterTarget: lib.filter.notMe,
    async content(event, trigger, player) {
      await event.target.damage("nocard");
    },
    ai: {
      order: 1,
      result: {
        target: -1.5
      },
      tag: {
        damage: 1
      }
    }
  }

