xianding:qingjiao.code:
{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    filter(event, player) {
      const hs = player.getCards("h");
      return hs.length > 0 && hs.every((card) => lib.filter.cardDiscardable(card, player, "qingjiao"));
    },
    async content(event, trigger, player) {
      await player.chooseToDiscard({ forced: true, position: "h", selectCard: player.countCards("h") });
      const evt = trigger.getParent();
      if (evt && evt.getParent && !evt.qingjiao) {
        evt.qingjiao = true;
        const next = game.createEvent("qingjiao_discard", false, evt.getParent());
        next.player = player;
        next.setContent(async (event2, trigger2, player2) => {
          const hs = player2.getCards("he");
          if (!hs.length) {
            return;
          }
          await player2.discard({ cards: hs });
        });
      }
      const list = [];
      const typelist = [];
      const getType = (card) => get.subtype(card) || card.name;
      for (const node of ui.cardPile.childNodes) {
        const typex = getType(node);
        if (typelist.includes(typex)) {
          continue;
        }
        list.push(node);
        typelist.push(typex);
        if (list.length >= 8) {
          break;
        }
      }
      if (list.length < 8) {
        for (const node of ui.discardPile.childNodes) {
          const typex = getType(node);
          if (typelist.includes(typex)) {
            continue;
          }
          list.push(node);
          typelist.push(typex);
          if (list.length >= 8) {
            break;
          }
        }
      }
      await player.gain({ cards: list, animate: "gain2" });
    }
  }

xianding:spzhuilie.code:
{
    mod: {
      targetInRange(card) {
        if (card.name === "sha") {
          return true;
        }
      }
    },
    audio: 2,
    trigger: { player: "useCardToTargeted" },
    filter(event, player) {
      return event.card && event.card.name === "sha" && !player.inRange(event.target);
    },
    forced: true,
    logTarget: "target",
    async content(event, trigger, player) {
      const next = player.judge((card) => {
        const type = get.subtype(card);
        return ["equip1", "equip4", "equip3", "equip6"].includes(type) ? 6 : -6;
      });
      next.judge2 = function(result2) {
        return result2.bool;
      };
      const result = await next.forResult();
      if (trigger.getParent().addCount !== false) {
        trigger.getParent().addCount = false;
        const stat = player.getStat();
        if (stat && stat.card && stat.card.sha) {
          stat.card.sha--;
        }
      }
      if (result.bool === true) {
        const map = trigger.customArgs;
        const id = trigger.target.playerid;
        if (!map[id]) {
          map[id] = {};
        }
        if (typeof map[id].extraDamage !== "number") {
          map[id].extraDamage = 0;
        }
        map[id].extraDamage += trigger.target.hp - 1;
      } else if (result.bool === false && get.type(result.card) !== "basic") {
        await player.loseHp();
        await player.gain(result.card);
      }
    },
    group: "spzhuilie_sha",
    subSkill: {
      sha: {
        silent: true,
        charlotte: true,
        trigger: { player: "useCardToTargeted" },
        filter(event, player) {
          return event.card && event.card.name === "sha";
        },
        async content(event, trigger, player) {
          trigger.target.addTempSkill("qinggang2");
          trigger.target.storage.qinggang2.add(trigger.card);
          trigger.target.markSkill("qinggang2");
        }
      }
    }
  }

