xianding:pytianjiang.code:
{
    audio: 2,
    trigger: {
      global: "phaseBefore",
      player: "enterGame"
    },
    forced: true,
    locked: false,
    filter(event, player) {
      return event.name !== "phase" || game.phaseNumber === 0;
    },
    async content(event, trigger, player) {
      const list = [];
      for (let i = 0; i < 2; i++) {
        const card = get.cardPile(
          (card2) => {
            if (get.type(card2) !== "equip") {
              return false;
            }
            return list.length === 0 || get.subtype(card2) !== get.subtype(list[0]);
          },
          false,
          "random"
        );
        if (card) {
          list.push(card);
        }
      }
      if (!list.length) {
        return;
      }
      await player.gain({
        cards: list,
        animate: "gain2"
      });
      for (const card of list) {
        await game.delay(1);
        if (!player.getCards("h").includes(card)) {
          continue;
        }
        player.$give(card, player, false);
        await player.equip(card);
      }
    },
    group: "pytianjiang_move"
  }

xianding:pytianjiang_move.code:
{
    audio: "pytianjiang",
    prompt: "将装备区里的一张牌移动至其他角色的装备区",
    enable: "phaseUse",
    position: "e",
    sourceSkill: "pytianjiang",
    filter(event, player) {
      return player.hasCards("e");
    },
    check() {
      return 1;
    },
    filterCard: true,
    filterTarget(event, player, target) {
      return target !== player && target.canEquip(ui.selected.cards[0], true);
    },
    prepare: "give",
    discard: false,
    lose: false,
    async content(event, trigger, player) {
      const { cards: cards2, target } = event;
      await target.equip(cards2[0]);
      if (cards2[0].name.indexOf("pyzhuren_") === 0 && !player.getCards("e").includes(cards2[0])) {
        await player.draw(2);
      }
    },
    ai: {
      order: (item, player) => {
        if (player.hasCard((i) => get.subtype(i) === "equip1", "h")) {
          return 11;
        }
        return 1;
      },
      expose: 0.2,
      result: {
        target(player, target) {
          if (ui.selected.cards.length) {
            const card = ui.selected.cards[0];
            const tv = get.value(card, target);
            const sub = get.subtype(card);
            if (sub === "equip1") {
              let ev = Infinity;
              const te = target.getEquips(1);
              if (!te.length) {
                return tv;
              }
              for (const equip of te) {
                ev = Math.min(ev, get.value(equip));
              }
              if (card.name.indexOf("pyzhuren_") === 0) {
                return 2 + tv - ev;
              }
              return tv - ev;
            }
            if (target.hasCard((i) => get.subtype(i) === sub, "he")) {
              return 0;
            }
            const pv = get.value(card, player);
            if (pv > 0 && Math.abs(tv) <= pv) {
              return 0;
            }
            return tv;
          }
          return 0;
        }
      }
    }
  }

