      });
    },
    async cost(event, trigger, player) {
      if (!["identity", "guozhan"].includes(get.mode())) {
        event.result = await player.chooseTarget((card, player2, target) => {
          return target.isFriendOf(player2) && target.countDiscardableCards(player2, "hej") > 0;
        }, get.prompt2(event.skill)).set("ai", (target) => {
          let min = 6;
          if (target.hasCard((card) => {
            const val = get.value(card, target);
            if (val < 0 && card.name !== "tengjia") {
              return true;
            }
            if (val < min) {
              min = val;
            }
          }, "e")) {
            return 10;
          }
          if (target.hasCard((card) => {
            const eff = get.effect(
              target,
              {
                name: card.viewAs || card.name,
                cards: [card]
              },
              target,
              target
            );
            if (eff < 0) {
              return true;
            }
            if (eff < min) {
              min = eff;
            }
          }, "j")) {
            return 10;
          }
          if (!get.event().discard) {
            return 0;
          }
          if (min > 6 && target.countCards("h")) {
            min = 6;
          }
          return 7 - min - 1 / (1 + target.countCards("h"));
        }).set(
          "discard",
          game.hasPlayer((current) => {
            if (current.isFriendOf(player)) {
              return false;
            }
            const values = {};
            current.countCards("e", (card) => {
              const color = get.color(card);
              if (!values[color]) {
